window.SHIJING_YI = {"gf-001": ["雎鸠关关叫着，停在河心沙洲上。", "美好贤淑的姑娘，正是君子的好配偶。", "长短不齐的荇菜，在水里左右漂动。", "美好贤淑的姑娘，日夜都在思念追求。", "追求不到手，醒着睡着都想她。", "想啊想啊，翻来覆去睡不着。", "长短不齐的荇菜，左右采摘起来。", "美好贤淑的姑娘，弹琴鼓瑟来亲近她。", "长短不齐的荇菜，左右挑选起来。", "美好贤淑的姑娘，敲钟打鼓让她快乐。"], "gf-006": ["桃树少壮娇嫩，花开红艳艳。", "这姑娘出嫁了，会让家庭和美。", "桃树少壮娇嫩，果实结得饱满。", "这姑娘出嫁了，会让家室安宁。", "桃树少壮娇嫩，叶子密密葱葱。", "这姑娘出嫁了，会让家人融洽。"], "gf-042": ["娴静的姑娘多么美，在城角等着我。", "躲起来看不见，挠头徘徊不定。", "娴静的姑娘多么俏，送我一支红管。", "红管亮闪闪，喜爱你的美丽。", "从牧场带回嫩茅，实在美又奇特。", "不是茅草本身美，是美人送的才美。"], "gf-091": ["青青的是你的衣领，悠悠的是我的心。", "纵然我不去，你就不肯再捎个音信？", "青青的是你的佩玉，悠悠的是我的思念。", "纵然我不去，你就不肯来？", "来回踱步啊，在城楼上啊。", "一天不见面，就像隔了三个月。"], "gf-129": ["芦苇苍苍一片，白露凝成了霜。", "我所怀念的那人，就在水的那一边。", "逆流去追寻，道路险阻又漫长。", "顺流去追寻，仿佛就在水中央。", "芦苇萋萋茂盛，白露还没干。", "我所怀念的那人，就在水草岸边。", "逆流去追寻，道路险阻又难攀。", "顺流去追寻，仿佛就在水中小洲上。", "芦苇一片繁密，白露还未消尽。", "我所怀念的那人，就在水边岸头。", "逆流去追寻，道路迂回又偏右。", "顺流去追寻，仿佛就在水中沙洲上。"], "gf-058": ["那汉子笑嘻嘻，抱着布来换丝。", "不是真来换丝，是来和我商量婚事。", "送你渡过淇水，一直到顿丘。", "不是我故意拖延，是你没有好媒人。", "请你别生气，就以秋天为婚期。", "登上那破墙头，遥望复关方向。", "望不见复关来人，眼泪涟涟。", "终于望见复关来人，又说又笑。", "你占卜又算卦，卦象没有凶言。", "用你的车来接，把我的嫁妆搬走。", "桑叶还未落时，叶子润泽肥厚。", "可叹斑鸠啊，不要贪吃桑葚。", "可叹女子啊，不要与男子沉迷。", "男子沉迷了，还可以解脱。", "女子沉迷了，就无法解脱！", "桑叶落了，又黄又掉。", "自从我嫁到你家，三年吃尽苦日子。", "淇水浩浩汤汤，溅湿了车帷。", "女子没有过错，男子却改变了行为。", "男子没有准则，三心二意。", "做了三年媳妇，家里的事没有不操劳的。", "早起晚睡，没有一天清闲。", "你的心愿满足了，就开始对我暴虐。", "兄弟不了解实情，还咧嘴笑我。", "静下心来想想，只能独自伤悼。", "本说与你白头到老，到老却使我怨恨。", "淇水还有岸，洼地还有边。", "儿时一起玩耍，说说笑笑和乐，誓言诚恳旦旦，却不想会违背。", "违背了也不再想，也就算了吧！"], "xy-007": ["采薇菜啊采薇菜，薇芽刚刚冒出来。", "说回家啊说回家，一年又快到尽头。", "顾不上家室，只因玁狁侵扰。", "没空安居，只因玁狁侵扰。", "采薇菜啊采薇菜，薇叶正柔嫩。", "说回家啊说回家，心里更忧愁。", "忧心如火烧，又饥又渴。", "戍守还没定处，没人替我捎家信。", "采薇菜啊采薇菜，薇茎已变硬。", "说回家啊说回家，又到十月阳月。", "王事没完没了，没空安歇。", "忧心极痛，怕此行回不来！", "那盛开的是什么？", "是棠棣的花。", "那大车是什么？", "是将帅的战车。", "战车已驾好，四匹公马高大强壮。", "哪敢安居定处？", "一月里多次告捷。", "驾着那四匹公马，马儿强壮有力。", "将帅倚靠它，兵士靠它掩护。", "四马行列整齐，象弭鱼皮箭袋。", "怎能不天天戒备？", "玁狁太紧急了！", "从前我离去时，杨柳依依飘拂。", "如今我归来时，雨雪霏霏纷飞。", "道路走得慢吞吞，又渴又饥。", "我心悲伤，谁知我的哀痛！"], "gf-002": ["葛藤蔓延开来，铺满山谷，叶子青青茂盛。", "黄鸟飞来飞去，停在灌木上，叫声和谐。", "葛藤蔓延开来，铺满山谷，叶子密密层层。", "割下煮熟，织成细布粗布，穿上也不厌烦。", "告诉女师，说我要回娘家了。", "洗一洗贴身衣，浣一浣外衣。", "哪些要洗哪些不用，好回家看望父母。"], "gf-003": ["采啊采卷耳，却采不满一浅筐。", "心里想念那人，把筐搁在大路边。", "登上那高峻山石，我的马儿腿软无力。", "姑且斟满那金杯，好让自己别老想着。", "登上那高冈，我的马儿眼花力尽。", "姑且斟满那牛角杯，好让自己别太伤怀。", "登上那乱石山，马病了，仆人也累垮了，叫人怎不愁叹。"], "gf-004": ["南方有棵弯树，葛藤缠绕上去。", "快乐的君子啊，福禄安抚着他。", "南方有棵弯树，葛藤覆盖上去。", "快乐的君子啊，福禄护持着他。", "南方有棵弯树，葛藤萦绕上去。", "快乐的君子啊，福禄成就了他。"], "gf-005": ["螽斯振翅，密密成群。", "愿你子孙众多，兴旺有为。", "螽斯振翅，嗡嗡作响。", "愿你子孙绵延，代代不绝。", "螽斯振翅，聚在一起。", "愿你子孙和睦，安居繁盛。"], "gf-007": ["兔网密密张着，木桩敲得丁丁响。", "威武的勇士，是公侯的屏障。", "兔网密密张着，设在大路口。", "威武的勇士，是公侯的好帮手。", "兔网密密张着，设在树林中。", "威武的勇士，是公侯的心腹。"], "gf-008": ["采啊采车前草，去采它吧。", "采啊采车前草，采到一些了。", "采啊采车前草，一颗颗捡起来。", "采啊采车前草，一把把捋下来。", "采啊采车前草，提起衣襟兜着。", "采啊采车前草，掖起衣襟装满。"], "gf-009": ["南方有高树，却不能在下休息。", "汉水有游女，却不能去追求。", "汉水太宽了，游不过去啊。", "江水太长了，筏也渡不过。", "杂乱柴薪翘起，去割那荆条。", "那姑娘若出嫁，我愿喂好她的马。", "汉水太宽了，游不过去啊。", "江水太长了，筏也渡不过。", "杂乱柴薪翘起，去割那蒌蒿。", "那姑娘若出嫁，我愿喂好她的小马。", "汉水太宽了，游不过去啊。", "江水太长了，筏也渡不过。"], "gf-010": ["沿着汝水堤岸，砍那树枝树干。", "见不到心上人，饿得像清晨空腹。", "沿着汝水堤岸，砍那新生枝条。", "见到了心上人，他没有把我疏远。", "鲂鱼累得红了尾，王室危急如火烧。", "虽说危急如火，父母却近在身边。"], "gf-011": ["麒麟的蹄子，公子们仁厚有为，麒麟啊！", "麒麟的额头，公族们仁厚有为，麒麟啊！", "麒麟的角，同族们仁厚有为，麒麟啊！"], "gf-012": ["喜鹊筑好巢，鸠鸟住进去。", "这姑娘出嫁，百辆车来迎接。", "喜鹊筑好巢，鸠鸟占住它。", "这姑娘出嫁，百辆车来护送。", "喜鹊筑好巢，鸠鸟挤满了。", "这姑娘出嫁，百辆车来成礼。"], "gf-013": ["到哪儿采白蒿？", "在池塘水洲上。", "采来做什么用？", "供公侯祭祀用。", "到哪儿采白蒿？", "在山涧当中。", "采来做什么用？", "供公侯宗庙用。", "假发高高梳起，早晚忙公事。", "假发盛美许多，事情完了回家。"], "gf-014": ["草虫喓喓叫，阜螽蹦蹦跳。", "见不到心上人，心里忧愁忡忡。", "已经见到了，已经相会了，心才放下来。", "登上那南山，去采蕨菜。", "见不到心上人，心里忧愁不安。", "已经见到了，已经相会了，心里才欢喜。", "登上那南山，去采薇菜。", "见不到心上人，心里悲伤。", "已经见到了，已经相会了，心里才平静。"], "gf-015": ["到哪儿采浮萍？", "南边山涧旁。", "到哪儿采水藻？", "在那流水洼里。", "用什么盛它？", "方筐和圆筥。", "用什么煮它？", "三脚锅和釜。", "在哪儿祭奠？", "宗庙窗户下。", "谁来主祭？", "那位恭敬的少女。"], "gf-016": ["甘棠树荫浓密，别剪别砍，召伯曾在这住过。", "甘棠树荫浓密，别剪别毁，召伯曾在这歇过。", "甘棠树荫浓密，别剪别折，召伯曾在这停过。"], "gf-017": ["路上露水湿漉漉，哪不想早赶夜路，只怕露水太重。", "谁说麻雀没有角？", "凭什么啄穿我的屋？", "谁说你没有家室？", "凭什么逼我上公堂？", "就算逼我上公堂，成家条件也不够！", "谁说老鼠没有牙？", "凭什么打穿我的墙？", "谁说你没有家室？", "凭什么逼我打官司？", "就算逼我打官司，我也不会依从你！"], "gf-018": ["羔羊皮袍，白丝缝成五紽。", "办完公事回家吃饭，步态从容悠闲。", "羔羊皮衣，白丝缝成五緎。", "步态从容悠闲，从公衙回家吃饭。", "羔羊皮缝，白丝缝成五总。", "步态从容悠闲，办完公事回家吃饭。"], "gf-019": ["雷声隆隆，在南山向阳处。", "为何离开这里，不敢稍稍闲暇？", "忠厚的君子啊，回来吧回来吧！", "雷声隆隆，在南山旁边。", "为何离开这里，不敢稍稍歇息？", "忠厚的君子啊，回来吧回来吧！", "雷声隆隆，在南山脚下。", "为何离开这里，不敢稍稍安处？", "忠厚的君子啊，回来吧回来吧！"], "gf-020": ["梅子掉落了，树上还剩七成。", "追求我的小伙子们，趁这吉日来吧。", "梅子掉落了，树上只剩三成。", "追求我的小伙子们，就在今天来吧。", "梅子掉落了，用浅筐来盛。", "追求我的小伙子们，开口说一声就行。"], "gf-021": ["那些小星星闪烁，三三五五在东方。", "急急忙忙夜里赶路，早晚都在办公事。", "只因命运各不同！", "那些小星星闪烁，是参星和昴星。", "急急忙忙夜里赶路，还抱着被子帐子。", "只因命运比不上别人！"], "gf-022": ["江有支流，那人回去了，却不带上我。", "不带上我，以后她会后悔。", "江有沙洲，那人回去了，却不跟我在一起。", "不跟我在一起，以后她会忧愁。", "江有支河，那人回去了，却不来看我。", "不来看我，我只好长啸当歌。"], "gf-023": ["野地里有只死獐，用白茅包起来。", "有位姑娘春心萌动，好男儿去挑逗她。", "林中有丛生小树，野地里有只死鹿。", "白茅捆扎整齐，姑娘美如美玉。", "慢慢地轻轻地来，别动我的佩巾，别让狗叫起来。"], "gf-024": ["怎么那样浓艳，像唐棣的花？", "怎能不端庄和美？", "那是王姬的车驾。", "怎么那样浓艳，花开如桃李？", "是平王的孙女，齐侯的儿子。", "拿什么来钓鱼？", "用丝线绞成钓绳。", "齐侯的儿子，平王的孙女。"], "gf-025": ["芦苇茁壮生长，一箭射出五头母猪，驺虞啊真了不起！", "蓬蒿茁壮生长，一箭射出五头大猪，驺虞啊真了不起！"], "gf-026": ["漂着那柏木小船，也随着流水漂荡。", "心里不安睡不着，像有难言的忧愁。", "不是我没有酒，可以用来遨游散心。", "我的心不是镜子，不能什么都容纳。", "虽有兄弟，却不能依靠。", "去向他们诉说，却碰上他们发怒。", "我的心不是石头，不能随便转动。", "我的心不是席子，不能随便卷起。", "仪容举止端庄，不能被人挑剔贬损。", "忧愁悄悄压在心头，被那群小人怨恨。", "遭遇的苦难已经很多，受的欺侮也不少。", "静下心来想想，醒来便拍胸痛哭。", "太阳啊月亮啊，为何轮流亏缺不明？", "心里的忧愁啊，像一件洗不净的脏衣。", "静下心来想想，却不能振翅高飞。"], "gf-027": ["绿衣啊绿衣，绿上衣黄里子。", "心里的忧愁啊，何时才能停止！", "绿衣啊绿衣，绿上衣黄下裳。", "心里的忧愁啊，何时才能忘掉！", "绿丝啊绿丝，是你亲手整理的。", "我想念故人，让我少些过失！", "细布粗布衣，穿上凉飕飕像有风。", "我想念故人，实在合我的心意！"], "gf-028": ["燕子双双飞，羽毛参差不齐。", "这人要出嫁远行，送到野外很远。", "望啊望不到了，眼泪如雨下。", "燕子双双飞，上下翻飞。", "这人要出嫁远行，远远送她上路。", "望啊望不到了，站着哭泣。", "燕子双双飞，叫声上下回荡。", "这人要出嫁远行，送到南方。", "望啊望不到了，实在让我心伤。", "仲氏可信可靠，心地诚实深远。", "又温和又贤惠，谨慎修身。", "念着先君的叮嘱，来勉励我这寡人。"], "gf-029": ["太阳啊月亮啊，照临下方大地。", "竟有这样的人啊，不再像从前那样待我。", "心里怎能安定？", "难道不肯顾念我。", "太阳啊月亮啊，覆盖下方大地。", "竟有这样的人啊，不再和我相好。", "心里怎能安定？", "难道不肯回报我。", "太阳啊月亮啊，从东方升起。", "竟有这样的人啊，好话一句也没有。", "心里怎能安定？", "叫人怎么能忘。", "太阳啊月亮啊，从东方出来。", "父亲啊母亲啊，养我却不能到头。", "心里怎能安定？", "他待我全不按情理。"], "gf-030": ["又刮风又猛烈，见我就笑，轻薄戏谑，我心里却伤痛。", "又刮风又扬尘，难得肯来一次，不来往了，我思绪悠悠。", "又刮风又阴沉，整日阴霾，醒来睡不着，但愿他打喷嚏想我。", "天色阴沉沉，雷声轰隆隆，醒来睡不着，但愿他心里想我。"], "gf-031": ["战鼓咚咚响，士兵踊跃练兵。", "别人在国都筑漕城，我却独自南征。", "跟随孙子仲，去平定陈国和宋国。", "不让我回家，心里忧愁忡忡。", "住在哪里？歇在何处？", "马又丢失在哪里？", "到哪儿去找？", "在那树林底下。", "生死离合，曾与你约定。", "拉着你的手，与你一起到老。", "可叹相隔太远，不让我活着回去。", "可叹分离太久，不守对我的信约。"], "gf-032": ["和风从南方来，吹着那酸枣嫩心。", "枣心幼嫩娇弱，母亲多么辛劳。", "和风从南方来，吹着那酸枣成柴。", "母亲明慧善良，我却没有好品德。", "有处寒泉，在浚邑下方。", "儿子有七个，母亲仍旧劳苦。", "黄鸟鸣声清脆，唱得好听。", "儿子有七个，却无人安慰母心。"], "gf-033": ["雄雉飞起来，缓缓展翅。", "我心里思念啊，自己招来这阻隔。", "雄雉飞起来，叫声上下回荡。", "诚实的君子啊，实在让我心劳。", "望着那日月，思绪悠悠。", "道路那么远，何时才能回来？", "你们这些君子，不懂什么叫德行。", "不忌恨不贪求，怎么会不好。"], "gf-034": ["葫芦叶苦了，济水有深处可渡。", "水深就连衣淌过去，水浅就提起衣裳。", "济水涨满弥漫，野鸡喔喔叫。", "水满却不湿车轴，野鸡鸣叫求配偶。", "大雁雍雍和鸣，旭日刚刚升起。", "男子若要娶妻，趁着河冰未化。", "船夫招手叫渡，别人过河我不过。", "别人过河我不过，我在等我的友人。"], "gf-035": ["东风习习吹来，又阴又下雨。", "勉力同心过日子，不该动怒。", "采蔓菁采萝卜，难道只用叶子不要根？", "好话不要违背，愿与你同生共死。", "走路迟迟不前，心里有所不愿。", "送得不远就近，只送到门口。", "谁说苦菜苦，对我却甜如荠菜。", "你们新婚快乐，亲得像亲兄弟。", "泾水因渭水显得浊，但止水处仍清澈。", "你们新婚快乐，不肯再要我。", "别到我的鱼梁去，别打开我的鱼篓。", "自身尚不被容纳，哪顾得上以后。", "遇到水深的地方，用筏用船渡过。", "遇到水浅的地方，游泳淌过去。", "家中有的没有的，我都勉力去张罗。", "凡是邻里有灾难，我都爬着去救助。", "你不能爱护我，反把我当仇人。", "既阻绝我的好意，好比货物卖不出去。", "从前生活恐惧穷困，与你共患难。", "如今生活安定了，却把我比作毒物。", "我有美味的腌菜，也可用来过冬。", "你们新婚快乐，拿我来挡穷日子。", "你凶暴又发怒，把劳苦活都丢给我。", "不念从前情分，也曾恩爱过我。"], "gf-036": ["天黑了，天黑了！", "为何还不回去？", "若非为了君主，何必站在露水中！", "天黑了，天黑了！", "为何还不回去？", "若非为了君主之身，何必陷在泥泞中！"], "gf-037": ["旄丘上的葛藤啊，节儿怎么那样长？", "叔啊伯啊，为何拖延这么多天？", "为何安居不动？", "一定有伴同来！", "为何耽搁这么久？", "一定有缘故！", "狐裘毛茸茸，不是车子不向东。", "叔啊伯啊，没有人肯同情我。", "又小又卑微啊，流离失所的人。", "叔啊伯啊，装聋充耳不闻。"], "gf-038": ["鼓声简简响，正要跳万舞。", "太阳正当中，他站在最前排。", "高大的人多么魁梧，在公庭跳万舞。", "力气大如虎，握缰绳整齐如丝带。", "左手拿龠管，右手持雉羽。", "脸色红得像染赭，公侯赐他一杯酒。", "山上有榛树，洼地有甘草。", "心里想的是谁？", "西方那位美人。", "那位美人啊，是西方来的人啊。"], "gf-039": ["那泉水涓涓流，也流入淇水。", "心里怀念卫国，没有一天不想。", "美丽的同姓姐妹，且与她们商量。", "出门住在泲地，饯行喝在祢邑。", "女子出嫁远行，远离父母兄弟。", "问候各位姑姑，连带各位姐姐。", "出门住在干地，饯行喝在言地。", "涂上车油安好辖，掉转车头往前走。", "赶到卫国去，该不会有妨害吧？", "我想念肥泉，为此长长叹息。", "想念须邑和漕邑，我心悠悠。", "驾车出去游一游，好排遣我的忧愁。"], "gf-040": ["从北门走出来，心里忧愁沉沉。", "既寒酸又贫穷，没人知道我的艰难。", "罢了罢了！", "这是上天安排的，还能说什么！", "王室差事派给我，政事一股脑加给我。", "我从外面回家，家里人轮番责备我。", "罢了罢了！", "这是上天安排的，还能说什么！", "王室差事逼着我，政事一股脑丢给我。", "我从外面回家，家里人轮番挫辱我。", "罢了罢了！", "这是上天安排的，还能说什么！"], "gf-041": ["北风凉飕飕，大雪纷纷扬。", "惠爱而喜欢我的人，携手一起走。", "还犹豫还迟疑？", "事情已经很紧急！", "北风呼呼响，大雪霏霏下。", "惠爱而喜欢我的人，携手一起回。", "还犹豫还迟疑？", "事情已经很紧急！", "不红的不是狐狸，不黑的不是乌鸦。", "惠爱而喜欢我的人，携手同车走。", "还犹豫还迟疑？", "事情已经很紧急！"], "gf-043": ["新台明晃晃，河水涨满满。", "本想找个俊俏郎，却是个癞蛤蟆不像样。", "新台高又敞，河水漫无边。", "本想找个俊俏郎，却是个丑家伙没个完。", "鱼网布好了，鸿雁却陷进去。", "本想找个俊俏郎，却得了个驼背丑人。"], "gf-044": ["两个孩子乘船走，影子随波漂荡。", "心里想念你们，忧愁难以平静！", "两个孩子乘船走，渐渐漂远消失。", "心里想念你们，该不会遭遇祸害吧？"], "gf-045": ["漂着那柏木小船，在那河中央。", "垂着两撮发的少年，正是我的意中人。", "到死也不变心。", "母亲啊苍天啊，怎么不体谅人啊！", "漂着那柏木小船，在那河边上。", "垂着两撮发的少年，正是我的好匹配。", "到死也不变心。", "母亲啊苍天啊，怎么不体谅人啊！"], "gf-046": ["墙上长蒺藜，扫也扫不净。", "内室里的话，说也说不得。", "若是说得出口，说出来也丑。", "墙上长蒺藜，除也除不掉。", "内室里的话，细说也说不清。", "若是细说出来，话就太长了。", "墙上长蒺藜，捆也捆不住。", "内室里的话，宣扬不得。", "若是宣扬出来，说出来也辱人。"], "gf-047": ["本该与君子偕老，头上副笄饰六珈。", "仪态雍容大方，如山如河，华服正相宜。", "你品德不好，又能怎么样呢？", "鲜艳啊鲜艳，那是画雉的礼服。", "黑发如云，不屑用假发。", "美玉充耳，象牙发簪，额头白净。", "怎么像天仙一样？", "怎么像帝女一样？", "鲜明啊鲜明，那是展衣。", "外罩细葛绉纱，是夏天的贴身衣。", "你眉清目秀，额头容颜美好。", "当真这样的人啊，是邦国的美人！"], "gf-048": ["到哪儿采菟丝？", "在沬乡那里。", "心里想的是谁？", "美丽的孟姜啊。", "约我在桑中，邀我到上宫，送我到淇水边上。", "到哪儿采麦子？", "在沬地北边。", "心里想的是谁？", "美丽的孟弋啊。", "约我在桑中，邀我到上宫，送我到淇水边上。", "到哪儿采蔓菁？", "在沬地东边。", "心里想的是谁？", "美丽的孟庸啊。", "约我在桑中，邀我到上宫，送我到淇水边上。"], "gf-049": ["鹌鹑双双飞，喜鹊对对行。", "这人品行不良，我还把他当兄长！", "喜鹊对对行，鹌鹑双双飞。", "这人品行不良，我还把他当君上！"], "gf-050": ["定星正当中，动工建楚宫。", "按日影测量方位，建造楚室。", "种上榛栗椅桐梓漆，将来好砍来做琴瑟。", "登上那废墟，眺望楚丘。", "望见楚丘和堂邑，还有大山和高丘。", "下来察看桑田。", "占卜说吉利，结果果然很好。", "好雨已经下过，吩咐那马夫。", "天晴一早驾车，歇在桑田边。", "他不只为人正直，心地诚实深远。", "高大母马有三千。"], "gf-051": ["彩虹出现在东方，没人敢用手指。", "女子出嫁远行，远离父母兄弟。", "早晨虹气在西方，整个早晨要下雨。", "女子出嫁远行，远离兄弟父母。", "竟有这样的人，一心只想婚姻。", "太没有信用，不懂命运规矩！"], "gf-052": ["看老鼠还有皮，人却没有威仪！", "人若没有威仪，不死还干什么？", "看老鼠还有牙，人却不知节制！", "人若不知节制，不死还等什么？", "看老鼠还有肢体，人却没有礼貌！", "人若没有礼貌，为何不快去死？"], "gf-053": ["旗杆上牛尾旗高扬，在浚邑郊外。", "白丝镶边，好马四匹。", "那美好的人啊，拿什么送给他？", "旗杆上鸟旗高扬，在浚邑都城。", "白丝编织，好马五匹。", "那美好的人啊，拿什么赠给他？", "旗杆上旌旗高扬，在浚邑城里。", "白丝缠绕，好马六匹。", "那美好的人啊，拿什么告诉他？"], "gf-054": ["赶着车快跑，回去吊唁卫侯。", "驱马路途悠悠，来到了漕邑。", "大夫跋山涉水追来，我心里忧愁。", "既然不赞成我，我也不能掉头回去。", "看你们并不高明，我的心思并不远。", "既然不赞成我，难道不能再渡河回去？", "看你们并不高明，我的思念遏不住。", "登上那山丘，去采贝母。", "女子多愁善感，也各有各的道理。", "许国人责备我，众人幼稚又狂妄。", "我走在田野上，麦子蓬蓬生长。", "求告那大邦，靠谁去投奔谁？", "大夫君子们，不要责备我。", "你们百般思虑，不如我自己要走的路。"], "gf-055": ["望那淇水湾，绿竹婀娜多姿。", "有位文雅君子，如切如磋，如琢如磨。", "庄严又威武，光明又轩昂。", "有位文雅君子，永远不能忘记。", "望那淇水湾，绿竹青青。", "有位文雅君子，充耳美玉晶莹，帽缝宝石如星。", "庄严又威武，光明又轩昂。", "有位文雅君子，永远不能忘记。", "望那淇水湾，绿竹密如席。", "有位文雅君子，如金如锡，如圭如璧。", "宽和又从容，倚着双重车栏。", "善于说笑风趣，却不过分刻薄。"], "gf-056": ["筑室隐居在山涧，高士心地宽广。", "独睡独醒独说话，发誓永不忘记。", "筑室隐居在山阿，高士多么安适。", "独睡独醒独自歌，发誓永不偏离。", "筑室隐居在高地，高士盘桓自在。", "独睡独醒独自宿，发誓不告别人。"], "gf-057": ["美人个子高挑，锦衣外罩罩衣。", "齐侯的女儿，卫侯的妻子。", "太子的妹妹，邢侯的姨，谭公是她妹夫。", "手如柔嫩茅芽，肤如凝结油脂，颈如天牛幼虫，齿如瓠瓜子，方额弯眉，巧笑现酒窝，美目顾盼生辉。", "美人个子高高，停车在近郊。", "四匹公马骄健，红绸马饰鲜明。", "雉羽车帘来上朝。", "大夫早些退朝，别让国君太劳累。", "黄河水浩浩荡荡，向北哗哗流。", "鱼网撒得刷刷响，鲟鱼鲤鱼扑扑跳。", "芦苇荻草高高挺，陪嫁姜女盛装多，武士们雄壮威武。"], "gf-059": ["细长的竹竿，用来在淇水钓鱼。", "难道不想念你？", "路远无法到达。", "泉源在左边，淇水在右边。", "女子出嫁远行，远离兄弟父母。", "淇水在右边，泉源在左边。", "巧笑露出白牙，佩玉脚步轻盈。", "淇水悠悠流，桧木桨松木舟。", "驾车出去游一游，好排遣我的忧愁。"], "gf-060": ["芄兰的枝条，童子佩着解结锥。", "虽然佩着解结锥，却不能体谅我。", "摆出成人模样，垂带晃悠悠。", "芄兰的叶子，童子佩着扳指。", "虽然佩着扳指，却不能与我匹配。", "摆出成人模样，垂带晃悠悠。"], "gf-061": ["谁说黄河宽？", "一根芦苇就能渡过。", "谁说宋国远？", "踮起脚就能望见。", "谁说黄河宽？", "连一条小船都容不下。", "谁说宋国远？", "一个早晨就能到。"], "gf-062": ["大哥啊多威武，是邦国的俊杰。", "大哥手执长殳，为王作前驱。", "自从大哥去了东方，头发乱如飞蓬。", "难道没有润发油？", "为谁打扮好容颜！", "盼着下雨吧下雨，太阳却亮晃晃出来。", "一心想念大哥，哪怕想得头疼也甘心。", "哪儿能得到忘忧草？", "种在北堂后面。", "一心想念大哥，使我心里伤痛。"], "gf-063": ["有狐狸慢慢走，在那淇水桥上。", "心里忧愁啊，那人没有裤子穿。", "有狐狸慢慢走，在那淇水渡口。", "心里忧愁啊，那人没有腰带。", "有狐狸慢慢走，在那淇水边上。", "心里忧愁啊，那人没有衣服。"], "gf-064": ["你送我木瓜，我回赠美玉琚。", "不是为了报答，是想永远相好！", "你送我木桃，我回赠美玉瑶。", "不是为了报答，是想永远相好！", "你送我木李，我回赠美玉玖。", "不是为了报答，是想永远相好！"], "gf-065": ["那边黍子一行行，稷苗正在长。", "走路迟迟缓缓，心里摇摇不安。", "了解我的人，说我心里忧愁；不了解的，问我有何希求。", "悠悠苍天啊，这是怎样的人啊？", "那边黍子一行行，稷穗正在抽。", "走路迟迟缓缓，心里如醉。", "了解我的人，说我心里忧愁；不了解的，问我有何希求。", "悠悠苍天啊，这是怎样的人啊？", "那边黍子一行行，稷子已经结实。", "走路迟迟缓缓，心里像噎住。", "了解我的人，说我心里忧愁；不了解的，问我有何希求。", "悠悠苍天啊，这是怎样的人啊？"], "gf-066": ["君子去服役，不知归期。", "何时才能到家？", "鸡已回窝栖息。", "太阳下山了，羊牛走下坡来。", "君子去服役，叫人怎能不想！", "君子去服役，没法按日月计算。", "何时才能团聚？", "鸡已栖在木桩上。", "太阳下山了，羊牛聚拢回来。", "君子去服役，但愿他不饥不渴！"], "gf-067": ["君子喜气洋洋，左手拿笙簧，右手招我去厢房，真快乐啊！", "君子乐陶陶，左手拿羽旗，右手招我去游遨，真快乐啊！"], "gf-068": ["激扬的河水，漂不走一捆柴薪。", "那些人啊，不与我一起戍守申地。", "想念啊想念，哪月才能回家啊？", "激扬的河水，漂不走一捆荆条。", "那些人啊，不与我一起戍守甫地。", "想念啊想念，哪月才能回家啊？", "激扬的河水，漂不走一捆蒲草。", "那些人啊，不与我一起戍守许地。", "想念啊想念，哪月才能回家啊？"], "gf-069": ["山谷中有益母草，干枯焦黄了。", "有女子被离弃，慨然叹息。", "慨然叹息，嫁人真是艰难。", "山谷中有益母草，晒得细长干了。", "有女子被离弃，长声号哭。", "长声号哭，嫁的人不好。", "山谷中有益母草，连根湿处也干了。", "有女子被离弃，抽泣哭泣。", "抽泣哭泣，后悔也来不及了。"], "gf-070": ["兔子缓缓走，野鸡却陷进罗网。", "我刚出生时，还没什么事；我出生以后，却碰上百般灾难。", "但愿睡着再不醒来乱动！", "兔子缓缓走，野鸡却陷进覆车网。", "我刚出生时，还没什么劳役；我出生以后，却碰上百般忧愁。", "但愿睡着再不醒来！", "兔子缓缓走，野鸡却陷进鸟网。", "我刚出生时，还没什么徭役；我出生以后，却碰上百般凶祸。", "但愿睡着再听不见！"], "gf-071": ["绵绵的葛藤，在河水边上。", "终究远离兄弟，称呼别人作父亲。", "称呼别人作父亲，却也不肯顾念我。", "绵绵的葛藤，在河水岸边。", "终究远离兄弟，称呼别人作母亲。", "称呼别人作母亲，却也不肯亲近我。", "绵绵的葛藤，在河水岸旁。", "终究远离兄弟，称呼别人作兄长。", "称呼别人作兄长，却也不肯过问我。"], "gf-072": ["那人去采葛啊，一天不见，就像隔了三个月！", "那人去采蒿啊，一天不见，就像隔了三个秋天！", "那人去采艾啊，一天不见，就像隔了三年！"], "gf-073": ["大车辘辘响，毛衣像荻草那样青。", "难道不想念你？", "怕你不敢答应。", "大车沉沉响，毛衣像美玉那样红。", "难道不想念你？", "怕你不敢私奔。", "活着各住一室，死了同葬一穴。", "说我不守信，有这明亮的太阳为证。"], "gf-074": ["丘中有麻田，那留着的子嗟。", "那留着的子嗟，愿他慢慢走来。", "丘中有麦田，那留着的子国。", "那留着的子国，愿他来吃饭。", "丘中有李树，那留着的人。", "那留着的人，送给我佩玉玖。"], "gf-075": ["黑衣多么合身，破了再给你改做。", "到你的馆舍去。", "回来时，我给你备好饭菜。", "黑衣多么好看，破了再给你改造。", "到你的馆舍去。", "回来时，我给你备好饭菜。", "黑衣多么宽大，破了再给你重做。", "到你的馆舍去。", "回来时，我给你备好饭菜。"], "gf-076": ["请仲子啊，别翻过我的里墙，别折断我的杞树。", "哪是舍不得树？", "是怕我的父母。", "仲子值得怀念，父母的话也可怕。", "请仲子啊，别翻过我的墙，别折断我的桑树。", "哪是舍不得树？", "是怕我的兄长们。", "仲子值得怀念，兄长们的话也可怕。", "请仲子啊，别翻过我的园，别折断我的檀树。", "哪是舍不得树？", "是怕别人闲话多。", "仲子值得怀念，别人闲话也可怕。"], "gf-077": ["叔去打猎了，巷里像没住人。", "难道真没住人？", "只是都不如叔啊。", "实在美又仁厚。", "叔去冬猎了，巷里没人喝酒。", "难道真没人喝酒？", "只是都不如叔啊。", "实在美又和好。", "叔去野外了，巷里没人骑马。", "难道真没人骑马？", "只是都不如叔啊。", "实在美又威武。"], "gf-078": ["叔去打猎，驾着四马车。", "握缰绳整齐如丝带，两边骖马像跳舞。", "叔在草泽中，火把一齐举起。", "赤膊空手打老虎，献给公侯处。", "请叔别太习惯冒险，当心伤着你。", "叔去打猎，驾着四匹黄马。", "两匹服马在前头，两匹骖马如雁行。", "叔在草泽中，火把一齐扬起。", "叔善于射箭，又善于驾车。", "忽而勒马不进，忽而纵马奔驰。", "叔去打猎，驾着四匹花马。", "两匹服马齐头并进，两匹骖马如左右手。", "叔在草泽中，火势正旺。", "叔的马慢下来，射箭也少了，解开箭筒盖，把弓装进袋。"], "gf-079": ["清邑的兵在彭地，四马披甲气势壮。", "两支矛上红缨重重，在河边游逛翱翔。", "清邑的兵在消地，四马披甲威风凛。", "两支矛上翎毛重重，在河边逍遥自在。", "清邑的兵在轴地，四马披甲乐陶陶。", "左边回旋右边抽刃，中军摆出好看姿态。"], "gf-080": ["羔裘润泽柔滑，实在正直又美好。", "那个人啊，舍命也不改节操。", "羔裘饰着豹皮，十分威武有力。", "那个人啊，是邦国主持正直的人。", "羔裘鲜明啊，三道装饰灿烂。", "那个人啊，是邦国的俊彦。"], "gf-081": ["沿着大路走啊，拉住你的袖口啊。", "别讨厌我啊，故旧之情不要一下抛掉！", "沿着大路走啊，拉住你的手啊。", "别嫌弃我啊，相好之情不要一下断绝！"], "gf-082": ["女的说鸡叫了，男的说明天还没亮。", "你起来看看夜色，启明星还亮灿灿。", "就要出去飞翔，射野鸭和大雁。", "射中了拿回来，与你一起烹调。", "做好菜来喝酒，与你白头偕老。", "琴瑟在旁弹奏，无不安静美好。", "知道你来关心我，把杂佩赠给你。", "知道你顺从我，把杂佩慰问你。", "知道你喜爱我，把杂佩报答你。"], "gf-083": ["有女子与我同车，容颜如木槿花。", "轻盈像要飞翔，佩着美玉琼琚。", "那位美丽的孟姜，实在美又文雅。", "有女子与我同行，容颜如木槿花英。", "轻盈像要飞翔，佩玉叮当作响。", "那位美丽的孟姜，美德令人难忘。"], "gf-084": ["山上有扶苏树，洼地有荷花。", "见不到子都那样的美男，却遇见这狂妄家伙。", "山上有高松，洼地有红蓼。", "见不到子充那样的好人，却遇见这狡黠少年。"], "gf-085": ["落叶啊落叶，风吹着你。", "叔啊伯啊，你来唱我和你。", "落叶啊落叶，风飘着你。", "叔啊伯啊，你来唱我应和你。"], "gf-086": ["那个狡黠少年啊，不跟我说话啊。", "只因你的缘故，使我吃不下饭啊。", "那个狡黠少年啊，不跟我吃饭啊。", "只因你的缘故，使我睡不安稳啊。"], "gf-087": ["你若惠然想我，提起衣裳蹚过溱水。", "你若不想我，难道没有别人？", "你这狂妄孩子真狂啊！", "你若惠然想我，提起衣裳蹚过洧水。", "你若不想我，难道没有别的男子？", "你这狂妄孩子真狂啊！"], "gf-088": ["你容貌丰满啊，在巷口等我啊，悔恨我没去送你。", "你身材壮盛啊，在堂前等我啊，悔恨我没去陪你。", "锦衣外罩罩衣，锦裳外罩罩裳。", "叔啊伯啊，驾车让我与你同行。", "锦裳外罩罩裳，锦衣外罩罩衣。", "叔啊伯啊，驾车让我与你同归。"], "gf-089": ["东门的广场，茜草长在山坡上。", "她的屋子很近，人却觉得很远。", "东门的栗树下，有整齐的人家。", "难道不想念你？", "是你不来就我！"], "gf-090": ["风雨凄凄凉，鸡叫喈喈响。", "已经见到君子，心里怎能不平静？", "风雨潇潇下，鸡叫胶胶响。", "已经见到君子，心病怎能不好？", "风雨暗如夜，鸡叫不停歇。", "已经见到君子，心里怎能不欢喜？"], "gf-092": ["激扬的河水，漂不走一捆荆条。", "终究兄弟稀少，只有我和你。", "不要听信别人的话，别人实在是欺骗你。", "激扬的河水，漂不走一捆柴薪。", "终究兄弟稀少，只有我们两人。", "不要听信别人的话，别人实在不可信。"], "gf-093": ["走出东门，女子多如云。", "虽然多如云，却不是我思念的人。", "白衣青巾的那位，才使我快乐。", "走出外城门，女子多如茅花。", "虽然多如茅花，却不是我思念所在。", "白衣红巾的那位，才可与我同乐。"], "gf-094": ["野地有蔓草，露珠圆圆落。", "有一位美人，眉清目秀美好。", "偶然相遇，正合我的心愿。", "野地有蔓草，露水浓浓的。", "有一位美人，美好眉清目秀。", "偶然相遇，与你一同藏起欢乐。"], "gf-095": ["溱水与洧水，正浩浩荡荡流。", "士子与女子，正手持兰草。", "女的说去看看吧？", "男的说已经去过了。", "再去看看吧？", "洧水外边，实在宽阔又快乐。", "士子与女子，互相调笑戏谑，赠送芍药花。", "溱水与洧水，水深清澈。", "士子与女子，人多挤满了。", "女的说去看看吧？", "男的说已经去过了。", "再去看看吧？", "洧水外边，实在宽阔又快乐。", "士子与女子，正要调笑戏谑，赠送芍药花。"], "gf-096": ["鸡已经叫了，朝堂已经满了人。", "不是鸡在叫，是苍蝇的声音。", "东方亮了，朝堂已经热闹了。", "不是东方亮了，是月亮的光。", "虫子飞来嗡嗡响，甘愿与你同入梦。", "朝会快散了，别让人讨厌我连累你。"], "gf-097": ["你动作敏捷啊，在狃山之间遇见我。", "并驾追两只大兽，拱手夸我灵巧。", "你容貌美盛啊，在狃山道上遇见我。", "并驾追两只公兽，拱手夸我好样。", "你身材壮盛啊，在狃山南面遇见我。", "并驾追两只狼，拱手夸我本事好。"], "gf-098": ["在门屏间等我啊，白丝充耳啊，加上琼华美玉啊。", "在庭院中等我啊，青丝充耳啊，加上琼莹美玉啊。", "在堂上等我啊，黄丝充耳啊，加上琼英美玉啊。"], "gf-114": ["蟋蟀进了堂屋，一年快到尽头。", "今天再不享乐，日月就要消逝。", "不要过分安乐，还要想到本职。", "喜乐而不荒废，贤士保持警醒。", "蟋蟀进了堂屋，一年即将逝去。", "今天再不享乐，日月就要过去。", "不要过分安乐，还要想到分外事。", "喜乐而不荒废，贤士勤奋敏捷。", "蟋蟀进了堂屋，服役的车子也歇了。", "今天再不享乐，日月就要溜走。", "不要过分安乐，还要想到忧患。", "喜乐而不荒废，贤士安闲自得。"], "gf-099": ["东方升起太阳啊，那位美丽的人，来到我屋里啊。", "来到我屋里啊，踩着我的足迹走来。", "东方升起月亮啊，那位美丽的人，来到我门内啊。", "来到我门内啊，踩着我出门的足迹。"], "xy-001": ["鹿儿呦呦叫着，在野地里吃艾蒿。", "我有尊贵的客人，弹瑟又吹笙。", "吹笙鼓簧来助兴，捧上满筐的礼物。", "人们真心待我好，把正道指给我看。", "鹿儿呦呦叫着，在野地里吃青蒿。", "我有尊贵的客人，美名格外昭显。", "待民不轻浮，君子当效法学习。", "我有美酒，请嘉宾宴饮逍遥。", "鹿儿呦呦叫着，在野地里吃芩草。", "我有尊贵的客人，鼓瑟又弹琴。", "鼓瑟弹琴，和乐又尽兴。", "我有美酒，用来欢愉嘉宾的心。"], "xy-002": ["四匹公马拉车不停蹄，大路弯弯又漫长。", "难道不想回家吗？", "王事没完没了，我心里悲伤。", "四匹公马拉车不停蹄，白马累得直喘息。", "难道不想回家吗？", "王事没完没了，没空安居歇息。", "鹊鸠翩翩飞，忽高忽低，落在丛生的柞树上。", "王事没完没了，没空奉养父亲。", "鹊鸠翩翩飞，飞了又停，落在丛生的枸杞上。", "王事没完没了，没空奉养母亲。", "驾着四匹白马，急急赶路飞驰。", "难道不想回家吗？", "所以作这首歌，把思母之情唱出来。"], "xy-003": ["花儿开得煌煌亮，开遍高原和洼地。", "使者匆匆赶路，常怕使命赶不及。", "我的马是小马驹，六条缰绳润如油。", "奔驰驱赶，到处询访商量。", "我的马是青黑色，六条缰绳细如丝。", "奔驰驱赶，到处征询计谋。", "我的马是白身黑鬣，六条缰绳光泽好。", "奔驰驱赶，到处商量权衡。", "我的马是灰杂色，六条缰绳配得匀。", "奔驰驱赶，到处咨询访求。"], "xy-004": ["棠棣花开，花萼鲜明亮丽。", "如今世上的人，没有比得上兄弟的。", "死丧的威胁来了，兄弟最牵挂。", "高原洼地聚拢来，兄弟互相寻访。", "鹡鸰停在原野，兄弟救急难。", "纵有好朋友，也只空长叹。", "兄弟墙内虽争执，对外却同心御侮。", "纵有好朋友，也难长久相助。", "丧乱平息了，既安定又安宁。", "虽有兄弟，难道反不如朋友吗？", "摆好笾豆食器，畅饮美酒尽兴。", "兄弟都到齐，和乐又亲热。", "妻子感情融洽，如同鼓瑟弹琴。", "兄弟和合了，和乐又沉醉。", "让你的家室安好，让你的妻儿快乐。", "细想细谋，确实是这样吧？"], "xy-005": ["伐木声丁丁响，鸟儿嘤嘤叫。", "从深谷飞出，迁到高树上。", "嘤嘤鸣叫，是在求友的回应。", "看那鸟儿，尚且求友声。", "何况人呢，怎能不求朋友？", "神明若听见，终会和乐又太平。", "伐木许许响，滤出清酒香。", "已有肥嫩的羊羔，请来各位父辈。", "宁可碰巧没来，别怪我不顾念。", "院子扫得干干净净，摆上八簋佳肴。", "已有肥壮的公羊，请来各位舅辈。", "宁可碰巧没来，别怪我失礼。", "在山坡伐木，滤出的酒满溢。", "笾豆摆得整齐，兄弟不要疏远。", "人若失了情义，干粮小事也能结怨。", "有酒就滤给我喝，没酒就去买给我。", "鼓声坎坎为我敲，舞步蹲蹲为我跳。", "等到我有空闲，再来饮这清酒吧。"], "xy-006": ["上天保佑你安定，根基十分牢固。", "使你福厚充足，哪样福分不赐给你？", "使你多多受益，无不丰盛富庶。", "上天保佑你安定，让你得福禄。", "事事无不顺宜，承受上天百般俸禄。", "赐你长远的福，只怕日子不够用。", "上天保佑你安定，事事无不兴旺。", "如山如丘，如冈如陵，如江河滚滚而来，无不日益增长。", "洁净准备祭食，用来孝敬献享。", "春夏秋冬四时祭，献给先公先王。", "尸祝传话说：赐你万寿无疆。", "神灵降临了，留给你许多福。", "百姓质朴老实，只求日常饮食。", "黎民百姓，都受你德泽感化。", "如月之常满，如日之东升。", "如南山般长寿，不亏缺不崩塌。", "如松柏般茂盛，无不承继繁衍。"], "xy-008": ["我出动战车，到那牧场去。", "从天子那里，召我前来。", "召集那些车夫，叫他们装载出发。", "王事多危难，情况很紧急。", "我出动战车，到那郊外去。", "竖起龟蛇旗，又立起旄旗。", "那些鸟隼旗和龟蛇旗，怎能不猎猎飘扬？", "忧心悄悄，车夫也憔悴。", "王命南仲，前往北方筑城。", "战车隆隆，旌旗鲜明。", "天子命我，在朔方筑城。", "赫赫南仲，扫除玁狁。", "从前我离去时，黍稷正开花。", "如今我归来时，雨雪满路途。", "王事多危难，没空安居。", "难道不想回家吗？", "只怕这紧急军令。", "草虫喓喓叫，蚱蜢蹦蹦跳。", "没见到君子，忧心忡忡。", "见到了君子，我心才放下。", "赫赫南仲，讨伐西戎。", "春日迟迟长，草木萋萋绿。", "黄莺喈喈叫，采蘩的人多又忙。", "抓了俘虏、带了敌众，这就要还归。", "赫赫南仲，玁狁已平定。"], "xy-009": ["那孤零零的杜梨，果实圆又亮。", "王事没完没了，一天接一天拖延。", "已到十月阳月，女子心伤痛，征夫该有空了吧。", "那孤零零的杜梨，叶子萋萋茂。", "王事没完没了，我心悲伤。", "草木萋萋绿，女子心悲苦，征夫该归来了！", "登上那北山，去采枸杞。", "王事没完没了，让父母为我忧。", "檀木车走得慢，四马疲惫不堪，征夫该不远了。", "车不来人也不回，忧心极痛。", "约期过了还不至，更加添忧虑。", "卜筮都说了，都说快到了，征夫已临近。"], "xy-010": ["鱼儿落入鱼篓，有黄颊鱼和鲨鱼。", "君子有酒，又美又多。", "鱼儿落入鱼篓，有鲂鱼和鳢鱼。", "君子有酒，又多又美。", "鱼儿落入鱼篓，有鲇鱼和鲤鱼。", "君子有酒，又美又丰。", "物产真多啊，而且真好啊。", "物产真美啊，而且齐全啊。", "物产真丰啊，而且合时啊。"], "xy-011": ["南方有好鱼，纷纷用罩来捕。", "君子有酒，嘉宾宴饮作乐。", "南方有好鱼，纷纷用汕来捕。", "君子有酒，嘉宾宴饮欢喜。", "南方有弯树木，甜瓠藤缠绕着。", "君子有酒，嘉宾宴饮安详。", "鹊鸠翩翩飞来，成群聚集到此。", "君子有酒，嘉宾再宴再欢。"], "xy-012": ["南山有莎草，北山有藜菜。", "快乐啊君子，是邦家的根基。", "快乐啊君子，万寿无穷期。", "南山有桑树，北山有杨树。", "快乐啊君子，是邦家的光荣。", "快乐啊君子，万寿无疆。", "南山有枸杞，北山有李树。", "快乐啊君子，是百姓的父母。", "快乐啊君子，美名传不息。", "南山有栲树，北山有杻树。", "快乐啊君子，怎能不长寿。", "快乐啊君子，德音更茂盛。", "南山有枸树，北山有楰树。", "快乐啊君子，怎能不黄发高寿。", "快乐啊君子，保佑你的后代。"], "xy-013": ["艾蒿长得高又长，露水清清润其上。", "见到了君子，我心畅快舒展。", "宴饮谈笑，因此有美誉安处。", "艾蒿长得高又长，露水瀼瀼落其上。", "见到了君子，如受宠如见光。", "他的德行不偏差，长寿令人难忘。", "艾蒿长得高又长，露水泥泥沾其上。", "见到了君子，宴乐又和悦。", "宜于兄宜于弟，美德寿又乐。", "艾蒿长得高又长，露水浓浓积其上。", "见到了君子，马辔垂饰晃悠悠。", "鸾铃和谐鸣，万福齐汇聚。"], "xy-014": ["露水浓又重，不见太阳晒不干。", "夜宴安详欢，不醉不回去。", "露水浓又重，落在茂草上。", "夜宴安详欢，在宗庙里敲钟奏乐。", "露水浓又重，落在杞棘上。", "显赫诚信的君子，无不有美德。", "桐树和椅树，果实累累垂。", "和乐平易的君子，无不有美仪。"], "xy-015": ["朱红的弓弦松开了，接受下来好好收藏。", "我有嘉宾，内心嘉许他。", "钟鼓已摆好，一天里大宴款待。", "朱红的弓弦松开了，接受下来载上车。", "我有嘉宾，内心喜悦他。", "钟鼓已摆好，一天里劝酒敬他。", "朱红的弓弦松开了，接受下来装进袋。", "我有嘉宾，内心喜爱他。", "钟鼓已摆好，一天里酬答他。"], "xy-016": ["莪蒿青青茂盛，生在山阿中间。", "见到了君子，快乐又有仪容。", "莪蒿青青茂盛，生在水中小洲。", "见到了君子，我心就欢喜。", "莪蒿青青茂盛，生在丘陵中间。", "见到了君子，赐我百朋厚礼。", "杨木船儿漂漂，载沉又载浮。", "见到了君子，我心才安歇。"], "xy-017": ["六月里忙碌不停，战车已整饬完毕。", "四匹公马强壮，载着军服旗章。", "玁狁气焰很盛，所以我们紧急。", "王命出征，来匡正王国。", "选配四匹黑马，训练合乎法则。", "就在这六月，军服已制成。", "军服制成后，先走三十里。", "王命出征，来辅佐天子。", "四匹公马长大，头颅高大昂扬。", "讨伐玁狁，建立大功。", "威严又恭敬，共同承担武事。", "共同承担武事，来安定王国。", "玁狁并不弱，盘踞在焦获。", "侵镐又侵方，一直到泾阳。", "旗帜绣着鸟纹，白旆鲜明飘扬。", "大战车十辆，先行开路。", "战车安稳，前俯后仰合度。", "四马壮健，壮健又驯熟。", "讨伐玁狁，直达大原。", "文武双全的吉甫，万邦的楷模。", "吉甫宴饮欢喜，受了许多福祉。", "从镐京归来，我行军日子长久。", "设酒招待朋友，烹鳖又脍鲤。", "座上有谁在？", "是孝友的张仲。"], "xy-018": ["去采苦菜吧，在那新开的田，在这初耕的地。", "方叔驾临了，战车多达三千。", "盾牌兵器演练，方叔率领着。", "驾着四匹青马，四马行列整齐。", "大路车朱红亮，竹席蔽车鱼皮箭袋，钩膺辔革齐全。", "去采苦菜吧，在那新开的田，在这乡野中间。", "方叔驾临了，战车多达三千。", "旌旗鲜明飘扬，方叔率领着。", "车毂缠皮衡木错采，八只鸾铃瑲瑲响。", "穿着命服，朱红蔽膝堂皇，葱色佩珩玱玱响。", "那疾飞的隼，飞上高天，也会停落下来。", "方叔驾临了，战车多达三千。", "盾牌兵器演练，方叔率领着。", "钲人敲鼓，陈列军阵训诫部队。", "显赫诚信的方叔，鼓声渊渊，整旅凯旋声阗阗。", "愚蠢的蛮荆，敢与大邦为仇。", "方叔是元老，能大展谋略。", "方叔率领着，抓俘虏获敌众。", "战车隆隆，声势如霆如雷。", "显赫诚信的方叔，征伐玁狁，蛮荆也来畏服。"], "xy-019": ["我的车已修好，我的马已配齐。", "四匹公马强壮，驾车向东去。", "猎车已备好，四马高大壮。", "东边有甫田的草，驾车去行猎。", "那人去夏猎，选好的徒众喧喧嚷嚷。", "竖起旗设起旄，在敖地搏兽。", "驾着四匹公马，四马神采奕奕。", "朱红蔽膝金色鞋，会同盟会依次排。", "扳指护臂已备好，弓箭已调好。", "射手已会齐，帮我堆起猎物。", "四匹黄马已驾好，两旁骖马不偏斜。", "驰驱合规矩，放箭必中破。", "马鸣萧萧，旌旗悠悠。", "步卒车夫不惊扰，大厨不必堆太满。", "那人出征归来，有闻名无喧声。", "确实是君子，真是大功告成。"], "xy-020": ["吉日是戊日，祭马祖又祈祷。", "猎车已备好，四马高大壮。", "登上大土阜，追逐成群的野兽。", "吉日是庚午，已选好我的马。", "野兽聚集处，母鹿成群麇麇。", "沿着漆沮追踪，来到天子猎场。", "望那原野中，大兽很多。", "奔跑的走的，或成群或成对。", "率领左右一齐上，好让天子安心乐。", "拉开我的弓，搭上我的箭。", "射中那小野猪，射死这大犀牛。", "用来宴请宾客，并且酌醴畅饮。"], "xy-021": ["大雁飞啊飞，翅膀肃肃响。", "那些人去服役，在野外辛劳。", "连及可怜的人，哀怜这些鳏寡。", "大雁飞啊飞，停落在沼泽中。", "那些人去筑墙，百堵墙都筑起。", "虽然辛劳，终能安居。", "大雁飞啊飞，哀鸣嗷嗷叫。", "通达的人，说我确是辛劳。", "愚昧的人，说我在炫耀骄矜。"], "xy-022": ["夜已到什么时辰了？", "夜还未尽，庭中火炬正亮。", "君子到来了，鸾铃声将将响。", "夜已到什么时辰了？", "夜还未消尽，庭中火炬晣晣明。", "君子到来了，鸾铃声哕哕响。", "夜已到什么时辰了？", "夜将近清晨，庭中火炬余辉在。", "君子到来了，可看见他的旌旗。"], "xy-023": ["那满满的流水，朝宗归于大海。", "疾飞的隼，飞了又停。", "可叹我的兄弟，邦国里的朋友。", "谁都不肯顾念乱局，谁没有父母？", "那满满的流水，水流汤汤浩荡。", "疾飞的隼，飞了又扬起。", "想到那些不守正道的，起身又徘徊。", "心里的忧愁，无法消除遗忘。", "疾飞的隼，沿着山陵飞。", "民间谣言四起，难道无人惩治？", "我的朋友们要警惕啊，谗言就要兴起。"], "xy-024": ["鹤在深泽鸣叫，声音传到原野。", "鱼潜在深渊，有时也在浅渚。", "那园子真可爱，种着檀树，树下是落叶。", "他山的石头，可以当磨刀石。", "鹤在深泽鸣叫，声音传到天上。", "鱼在浅渚，有时潜在深渊。", "那园子真可爱，种着檀树，树下是楮树。", "他山的石头，可以用来琢玉。"], "xy-025": ["祈父啊，我是王的爪牙卫士。", "为何把我推向忧患，无处安居？", "祈父啊，我是王的爪牙武士。", "为何把我推向忧患，无处归止？", "祈父啊，你实在不聪明。", "为何把我推向忧患？", "家有老母还等着我供养。"], "xy-026": ["皎皎白马驹，吃我场上的青苗。", "拴住它系住它，好留住整个今朝。", "所说的那个人，在哪里逍遥？", "皎皎白马驹，吃我场上的豆叶。", "拴住它系住它，好留住整个今夕。", "所说的那个人，在哪里做客？", "皎皎白马驹，翩然来到这里。", "你是公是侯，安逸享乐没完吗？", "珍惜你的优游，打消隐遁的念头。", "皎皎白马驹，在那空旷山谷。", "鲜草一束，那人如美玉。", "别把音信看得如金玉般贵重，而起疏远之心。"], "xy-027": ["黄鸟啊黄鸟，别停在楮树上，别啄我的粟。", "这邦的人，不肯善待我。", "说回去就回去，回到我的邦族。", "黄鸟啊黄鸟，别停在桑树上，别啄我的粱。", "这邦的人，不可与之结盟。", "说回去就回去，回到我的兄长们那里。", "黄鸟啊黄鸟，别停在柞树上，别啄我的黍。", "这邦的人，不可与之共处。", "说回去就回去，回到我的父辈们那里。"], "xy-028": ["我走在原野上，樗树遮天蔽日。", "因为婚姻的缘故，才来与你同住。", "你不畜养我，我就回我的邦家。", "我走在原野上，去采那蓫草。", "因为婚姻的缘故，才来与你同宿。", "你不畜养我，我就归去再想办法。", "我走在原野上，去采那葍草。", "不念旧姻情，去求你的新欢。", "并非因为她富有，只是喜新厌旧罢了。"], "xy-029": ["涧水清清流淌，南山幽幽深静。", "如竹丛般扎根，如松树般茂盛。", "兄和弟啊，要互相友好，不要相欺。", "继承先妣先祖，筑室百堵，门朝西南开。", "在此居住安处，在此欢笑言语。", "捆扎墙板阁阁响，夯土橐橐响。", "风雨被隔除，鸟鼠被驱走，君子在此居住。", "如人踮脚展翅，如箭棱角分明，如鸟张开翅膀，如雉鸡飞翔，君子登临其上。", "庭院平正宽敞，柱子高大笔直。", "正厅明亮豁亮，内室幽深宽敞，君子在此安宁。", "下铺蒲席上铺竹席，于是安然就寝。", "睡了又起，占问我的梦。", "吉梦是什么？", "是熊是罴，是虺是蛇。", "太卜占道：熊罴是生男的祥兆；虺蛇是生女的祥兆。", "若生了男孩，让他睡在床上。", "给他穿裳，给他玩玉璋。", "哭声洪亮喤喤，朱红蔽膝堂皇，将来是室家君王。", "若生了女孩，让她睡在地上。", "给她穿褓衣，给她玩纺砖。", "不犯错不擅作主张，只议酒食之事，不给父母添忧。"], "xy-030": ["谁说你没有羊？", "三百只成一群。", "谁说你没有牛？", "九十头大黄牛。", "你的羊来了，犄角密密攒聚。", "你的牛来了，耳朵湿湿扇动。", "有的下到山阿，有的在池边饮水，有的睡有的动。", "你的牧人来了，披蓑戴笠，有的背着干粮。", "毛色品类三十种，祭祀用牲都齐备。", "你的牧人来了，捡柴割草，分出雌雄。", "你的羊来了，谨慎又整齐，不亏损不散乱。", "手臂一挥，全都跟上来登上圈。", "牧人做了梦：梦见众变为鱼，龟旗变为鸟旗；太卜占道：众变鱼是丰年；旗变鸟旗是家室兴旺。"], "xy-031": ["高峻的南山，岩石层层峭立。", "赫赫的师尹，百姓都仰望你。", "忧心如火烧，不敢戏笑谈论。", "国运已断绝，你为何不监察！", "高峻的南山，山坡草木充实。", "赫赫的师尹，不公平成何体统。", "上天正降灾疫，丧乱又多又大。", "民怨没有好话，你却惨然不惩戒。", "尹氏太师，本是周室的柱石；掌握国政均衡，维系四方。", "辅弼天子，使百姓不迷茫。", "不体恤的苍天啊，不该让民众空乏。", "你不亲身过问，庶民就不信服。", "不问不用贤人，不要欺罔君子。", "平息乱局制止恶行，别让小人危害。", "琐碎的姻亲裙带，却给以厚任。", "苍天不公允，降下这大祸乱。", "苍天不慈惠，降下这大灾难。", "君子若来临政，能使民心平息。", "君子若公平，怨怒就会远离。", "不体恤的苍天啊，乱局没有安定。", "祸乱月月滋生，使百姓不得安宁。", "忧心如酒醉，谁在执掌国政？", "自己不亲理政事，终使百姓劳苦。", "驾着四匹公马，马儿脖子粗壮。", "我望四方，局促无处驰骋。", "正当你作恶正盛，矛头都对着你。", "一旦平息又高兴，又像互相劝酒。", "苍天不公平，我王不得安宁。", "不惩戒自己的心，反怨恨正直之人。", "家父作此诗，来追究王的祸根。", "愿你改变心意，来畜养万邦。"], "xy-032": ["正月里降了繁霜，我心忧伤。", "民间的谣言，也很猖狂。", "想到我孤单一人，忧心沉沉。", "哀叹我小心翼翼，愁病交加。", "父母生下我，为何使我受病痛？", "灾祸不在我前，也不在我后。", "好话出自口，坏话也出自口。", "忧心越来越重，因此遭受欺侮。", "忧心孤独，想到我没有俸禄。", "无辜的百姓，连臣仆一并遭殃。", "哀叹我们这些人，到哪里求生计？", "看乌鸦停在何处？", "停在谁家的屋上？", "望那林中，有的当柴有的当草。", "百姓如今正危殆，看天却昏昏梦梦。", "一旦天命有定，无人能胜过天。", "皇皇上帝啊，究竟憎恶谁？", "说山多么低，其实是冈是陵。", "民间的谣言，难道无人惩治。", "召来那些故老，询问占梦。", "都说自己圣明，谁分得出乌鸦雌雄！", "说天多么高，却不敢不弯腰。", "说地多么厚，却不敢不小步走。", "喊出这些话，有条理有根据。", "哀叹如今的人，为何像毒蛇蜥蜴？", "望那坡田，有茁壮的独苗。", "上天动摇我，像唯恐不能制伏我。", "他们求我时，唯恐得不到。", "得到后却仇视怠慢，也不重用我。", "心里的忧愁，像打了结。", "如今的政治，为何如此暴厉？", "大火正熊熊，难道有人能灭它？", "赫赫的宗周，被褒姒灭亡了！", "长久怀忧，又困于阴雨。", "车子已满载，却丢掉了夹板。", "货物要倾覆了，才喊伯来帮我！", "不要丢掉夹板，加固你的车辐。", "常看顾你的车夫，才不会倾覆货物。", "终能越过险阻，你们竟不在意。", "鱼在池沼里，也并不能安乐。", "即使潜伏着，也十分显露。", "忧心惨惨，想到国政的暴虐！", "他们有美酒，又有嘉肴。", "亲密结交邻里，姻亲往来热闹。", "想到我孤单一人，忧心殷殷。", "卑鄙的人有房屋，鄙陋的人有谷物。", "百姓如今无俸禄，上天降灾摧残。", "富人还好过，哀此孤独无依的人。"], "xy-033": ["十月交会之时，朔日是辛卯。", "日头有了蚀，也是大丑事。", "那月亮亏微，这太阳也亏微；如今下民，也十分悲哀。", "日月告示凶兆，不按常道运行。", "四方没有善政，不用贤良之人。", "那月亮被食，还可算常事；这太阳被食，为何不善。", "电光烨烨闪，不安又不善。", "百川沸腾，山顶猝然崩塌。", "高岸变成谷，深谷变成陵。", "哀叹如今的人，为何还不惩戒？", "皇父为卿士，番氏为司徒，家伯为宰，仲允为膳夫，棸子为内史，蹶氏管马，楀氏为师氏。", "艳妻气焰正盛，并居高位。", "这皇父啊，难道说不按时？", "为何派我劳作，却不来同我商量？", "拆了我的墙屋，田地全成污莱。", "还说我没伤害你，礼法本该如此。", "皇父自认很圣明，在向地建都城。", "选了三个办事官，实在多聚敛。", "不肯留下一个老臣，来守护我王。", "选有车马的人，迁居到向地。", "勉力做事，不敢诉说劳苦。", "无罪无过，谗言却嚣嚣。", "下民的灾孽，并非从天而降。", "当面谈笑背后憎，全是人为造成。", "悠悠我的乡里，也使我大病。", "四方有余裕，我独居忧愁。", "别人无不安逸，我独不敢休息。", "天命不循常道，我不敢学朋友去自图安逸。"], "xy-034": ["浩浩苍天，不长久施其德。", "降下丧乱饥馑，斩伐四方邦国。", "上天威怒猛烈，不考虑不谋划。", "放过那些有罪的，掩盖他们的罪过。", "像这些无罪的，却相随陷入苦难。", "周宗既已覆灭，无处安身止息。", "执政大夫离散居处，无人知我劳苦。", "三公大夫，不肯早晚尽职。", "邦君诸侯，不肯朝夕勤王。", "本望他们向善，反倒出去作恶。", "奈何啊苍天，正言不被听信。", "如同赶路远行，却无处可到。", "各位君子，各自敬慎自身。", "为何不相畏惧，不怕上天？", "战祸已成不消退，饥荒已成不顺遂。", "我这近侍之臣，日日憔悴忧伤。", "各位君子，不肯进谏劝告。", "顺耳的话就应答，谗言来了就退避。", "哀哉不能说话，并非舌头的过错，是自身受尽折磨。", "能言的人好过啊，巧言如流水，使自身处安乐！", "说到做官，既紧急又危险。", "说不可听从，就得罪天子；说可以听从，又招朋友怨恨。", "劝你迁到王都去。", "却说我还没有室家。", "忧思泣血，没有一句话不招怨恨。", "从前你离开居所，谁跟你去盖房子？"], "xy-035": ["上天威怒猛烈，布满下方土地。", "谋略邪僻不正，何日才能停止？", "好计不听从，坏计反而采用。", "我看这些谋略，也十分糟糕。", "附和又诽谤，也十分悲哀。", "谋划得好的，全都违背。", "谋划得不好的，全都依从。", "我看这些谋略，将落到何处。", "我的龟卜已厌烦，不再告诉我吉凶。", "谋士太多，所以事情不成。", "发言满庭，谁敢承担责任？", "如同与路人商量赶路，所以不得正道。", "哀哉这样谋划，不以先民为法程，不以大道为常经。", "只听浅近的话，只争浅近的话。", "如同在大路上盖房还到处问人，所以不能建成。", "国虽不大安定，有圣明的也有不圣明的。", "民虽不很富裕，有明哲的有善谋的，有肃敬的有治理的。", "如同泉水奔流，不要相随一齐败亡。", "不敢徒手搏虎，不敢徒步渡河。", "人只知其一，不知其他。", "战战兢兢，如临深渊，如履薄冰。"], "xy-036": ["小小的鸣鸠，展翅飞上高天。", "我心忧伤，思念往昔的先人。", "天亮还睡不着，怀想父母二人。", "明智圣哲的人，饮酒温和能自制。", "那昏昧无知的，一醉就自以为富足。", "各自敬慎仪容，天命不会再来。", "原野有豆菽，庶民去采它。", "螟蛉有幼子，蜾蠃背来养。", "教诲你的子女，用善道使他们相像。", "看那鹡鸰，边飞边鸣。", "我天天赶路，你月月远征。", "早起晚睡，不要有辱父母所生。", "交交叫的桑扈，沿着场圃啄粟。", "哀叹我贫病孤寡，怕要吃官司坐监牢。", "握着粟米去占卜，从哪里能得好兆？", "温和恭谨的人，如停在高树上。", "惴惴小心，如临深谷。", "战战兢兢，如履薄冰。"], "xy-037": ["那快乐的鸦鸟，归飞时从容安详。", "人们无不生活好，唯独我陷入忧患。", "对天有什么罪过？", "我的罪又是什么？", "心里的忧愁，该怎么办？", "平坦的大路，如今长满茂草。", "我心忧伤，痛楚如杵捣。", "和衣假寐长叹息，忧愁使人衰老。", "心里的忧愁，病痛如头痛。", "桑树和梓树，一定要恭敬。", "所瞻仰的无非父亲，所依靠的无非母亲。", "难道不属于皮毛？", "难道不附着里层？", "上天生下我，我的时运在哪里？", "那茂密的柳树，蝉鸣嘒嘒，有深深的渊水，芦苇密密。", "好比船随水流，不知到何处，心里忧愁，没空假寐。", "鹿儿奔跑，脚步伎伎缓。", "野鸡清晨啼叫，尚且求它的伴侣。", "好比伤残的树，病得没有枝条。", "心里的忧愁，难道无人知晓？", "看那投入网的兔子，尚有人放它走。", "路上有死人，尚有人掩埋他。", "君子的居心，竟如此忍心。", "心里的忧愁，眼泪已落下。", "君子听信谗言，如接受劝酒。", "君子不施恩惠，不慢慢推究。", "伐木要用绳子拉，劈柴要顺着纹理。", "放过真正有罪的，却把罪加给我。", "没有不高的山，没有不深的泉。", "君子不要轻易发言，有耳贴在墙边听。", "不要到我的鱼梁去，不要动我的鱼篓。", "我自身尚且不被容，哪有闲心思顾后事。"], "xy-038": ["悠悠苍天，如同父母啊。", "无罪无过，乱局却如此大。", "上天已够威猛，我确信自己无罪。", "上天太过放纵，我确信自己无辜。", "乱局初生时，谗言已被包容。", "乱局再起时，君子听信谗言。", "君子若发怒，乱局或许速止。", "君子若用贤，乱局或许速停。", "君子屡次盟誓，乱局反而滋长。", "君子信任盗贼，乱局因而暴烈。", "盗贼的话很甜，乱局因而加剧。", "他们并非恭敬守职，只是给王添病。", "高大的寝庙，是君子建造的。", "有序的大谋，是圣人制定的。", "别人有什么心，我能揣度出来。", "蹦跳的狡兔，遇上狗就被抓住。", "柔韧的好木，君子种植它。", "往来的流言，心里一一数着。", "夸大的大话，从口中说出。", "巧言如笙簧，脸皮真够厚。", "那是什么人？", "住在河边水草边。", "无拳力无勇气，专做乱的阶梯。", "腿烂又脚肿，你的勇气在哪里？", "诡计越来越多，你的党徒能有几个？"], "xy-039": ["那是什么人？", "他的心机很深险。", "为何经过我的鱼梁，却不进我的门？", "他跟随着谁？", "说是跟着暴公。", "两人一路同行，是谁造成这祸事？", "为何经过我的鱼梁，却不进来慰问我？", "从前不像现在，说我不可取。", "那是什么人？", "为何经过我的堂前路？", "我听见他的声音，却不见他的身影。", "对人不知愧，对天不知畏。", "那是什么人？", "他像一阵飘风。", "为何不从北边来？", "为何不从南边来？", "为何经过我的鱼梁？", "只搅乱我的心。", "你慢慢走时，也没空停歇。", "你急急走时，倒有空给车加油。", "你来一次吧，叫我多么盼望。", "你回来若进门，我心就舒畅。", "回来却不进门，就难测难知了。", "你来一次吧，使我心安。", "伯氏吹埙，仲氏吹篪。", "我与你如穿在一串，谅你却不理解我。", "摆出猪犬鸡三物，来诅咒你。", "若是鬼是蜮，就抓不到。", "却有这副面目，看人没有准则。", "作这首好歌，来穷究你的反复无常。"], "xy-040": ["花纹萋萋斐斐，织成这贝锦。", "那些进谗的人，也太过分了！", "嘴巴张得又大又阔，成了那南箕星。", "那些进谗的人，谁跟他们合谋。", "窃窃私语翩翩往来，谋划要陷害人。", "你说话要谨慎，有人会说你不可信。", "巧舌如簧幡幡反复，谋划要进谗言。", "难道不接受你的话？", "最终灾祸会转到你身上。", "骄横的人得意洋洋，劳苦的人忧心草草。", "苍天啊苍天，看看那些骄人，怜悯这些劳人。", "那些进谗的人，谁跟他们合谋？", "抓住那些谗人，扔给豺虎。", "豺虎若不吃，扔到北方荒地。", "北方若不收，扔给苍天处置！", "杨园的道路，紧靠着亩丘。", "寺人孟子，创作了这首诗。", "各位君子，敬请听一听。"], "xy-041": ["习习吹来的东风，伴随着雨。", "又恐又惧时，只有我与你。", "将安将乐时，你反而抛弃我。", "习习吹来的东风，伴随着旋风。", "又恐又惧时，把我抱在怀里。", "将安将乐时，弃我如遗忘。", "习习吹来的东风，山岳崔嵬高。", "没有草不死，没有树不萎。", "忘了我的大德，只记得我的小怨。"], "xy-042": ["那高高的莪蒿，其实不是莪是青蒿。", "哀哀父母，生我多么辛劳。", "那高高的莪蒿，其实不是莪是牡蒿。", "哀哀父母，生我多么劳瘁。", "小瓶空了，是大罍的耻辱。", "孤苦人活着，不如早些死去。", "没有父亲依靠什么？", "没有母亲仗恃什么？", "出门含着忧伤，进门如无家可归。", "父亲生下我，母亲哺育我。", "抚摸我畜养我，长大我教育我，照顾我反复看顾我，出入都抱着我。", "想报答这恩德。", "上天的恩德没有尽头！", "南山烈烈高峻，飘风发发猛烈。", "人们无不生活好，我独为何受害！", "南山律律高峻，飘风弗弗猛烈。", "人们无不生活好，我独不能终养！"], "xy-043": ["簋里饭食满满，枣木饭匙长柄弯。", "大路平如磨刀石，笔直如箭。", "君子走在上面，小人在旁注视。", "回望一眼，泪水潸然流出。", "东方远近各地，织机上空空如也。", "纠纠编的葛鞋，却要踏霜雪。", "轻佻的公子，走在那大路上。", "来来往往，使我心痛。", "有凛冽的旁出泉水，不要浸泡已砍的柴。", "忧苦失眠长叹，哀我劳苦的人。", "砍下的这些柴薪，还可以装车运走。", "哀我劳苦的人，也可以歇一歇。", "东方人的子弟，专职劳苦无人慰问。", "西方人的子弟，衣服华丽鲜亮。", "船夫的子弟，穿着熊罴皮裘。", "私家奴仆的子弟，充任百官职务。", "有人喝着酒，有人连浆也喝不上。", "有人佩着漂亮的璲，有人连杂佩也不够长。", "天上有银河，照映也有光。", "踮脚望那织女星，一天搬迁七次。", "虽则七次搬迁，织不成完整的布匹。", "明亮的牵牛星，却不能拉车箱。", "东方有启明，西方有长庚。", "弯弯的天毕星，排列在天空中。", "南方有箕星，却不能用来簸扬。", "北方有斗星，却不能用来舀酒浆。", "南方有箕星，缩着舌头像要吞。", "北方有斗星，西边的柄高高翘起。"], "xy-044": ["四月已是夏天，六月暑气渐盛。", "先祖难道不是人？为何忍心让我受苦？", "秋日凄凄凉，百草都枯萎。", "乱离痛苦啊，归向何处去？", "冬日烈烈寒，飘风发发猛。", "人们无不生活好，我独为何受害！", "山上有好花木，有栗有梅。", "竟被残贼摧残，不知谁的过错！", "看那泉水，有时清有时浊。", "我天天遭祸，怎能说得好过？", "滔滔江汉水，是南国的纲纪。", "尽瘁为官，难道无人亲我？", "不是鹌不是鸢，却想展翅飞上天。", "不是鳣不是鲔，却想潜逃入深渊。", "山上有蕨薇，洼地有杞桋。", "君子作此歌，只为诉说悲哀。"], "xy-045": ["登上那北山，去采枸杞。", "强壮的士子，朝夕忙公务。", "王事没完没了，让父母为我忧。", "普天之下，莫非王的土地；四海之内，莫非王的臣子。", "大夫分配不均，独我事务特别繁重。", "四马彭彭跑，王事纷纷忙。", "夸我还没老，称我正强壮。", "体力正刚健，经营奔走四方。", "有人安安闲闲歇着，有人尽瘁为国；有人偃卧在床，有人奔走不停。", "有人不知征召号令，有人惨惨辛劳；有人栖迟仰卧，有人王事缠身。", "有人沉湎饮酒作乐，有人惨惨怕获罪；有人进出空发议论，有人无事不做。"], "xy-046": ["不要推那大车，只会自己惹尘土。", "不要想那百般忧愁，只会自己生病痛。", "不要推那大车，尘土冥冥蔽天。", "不要想那百般忧愁，走不出光明。", "不要推那大车，尘土壅塞扑面。", "不要想那百般忧愁，只会自己加重负担。"], "xy-047": ["明明的上天，照临下方土地。", "我出征往西去，到达荒远的艽野。", "二月初吉出发，已经历寒又暑。", "心里的忧愁，毒苦得厉害。", "想起那些恭谨的人，涕泪零落如雨。", "难道不想回家吗？", "怕这罪网啊！", "从前我离去时，日月正当除旧布新。", "何时才能还归？", "一年又快到尽头。", "想到我孤单一人，事务却特别多。", "心里的忧愁，劳苦使我不得闲。", "想起那些恭谨的人，眷眷回头顾念！", "难道不想回家吗？", "怕这谴责恼怒。", "从前我离去时，日月正当温暖。", "何时才能还归？", "政事越来越紧迫。", "一年又到尽头，采艾蒿收豆菽。", "心里的忧愁，是自己招来的悲伤。", "想起那些恭谨的人，起身出门寄宿。", "难道不想回家吗？", "怕这反覆无常。", "可叹你们君子，不要常图安处。", "恭敬供职你的位子，与正直之人相交。", "神明听见了，会以善道待你。", "可叹你们君子，不要常图安息。", "恭敬供职你的位子，喜好正直之道。", "神明听见了，会赐你大福。"], "xy-048": ["敲钟将将响，淮水汤汤流，忧心又伤痛。", "善人君子，怀念诚信难忘。", "敲钟喈喈响，淮水湝湝流，忧心又悲哀。", "善人君子，德行不邪僻。", "敲钟又击大鼓，淮水有三洲，忧心又焦虑。", "善人君子，德行不欺诈。", "敲钟钦钦响，鼓瑟又鼓琴，笙磬同声和。", "奏雅乐奏南乐，用籥舞也不乱节。"], "xy-049": ["蒺藜楚楚丛生，去砍除它的刺。", "从前为何这样做？", "为了种植黍稷。", "我的黍长得与与茂，我的稷长得翼翼齐。", "我的仓已满，我的庾堆积成亿。", "用来做酒食，用来献享祭祀，请尸安坐劝侑，祈求大福。", "济济跄跄有威仪，洗净你的牛羊，前往冬祭秋祭。", "有的剥皮有的烹煮，有的陈设有的捧进。", "祝官在庙门祭，祀事十分明备。", "先祖来到堂上，神保前来飨用。", "孝孙有庆赏，回报以大福，万寿无疆！", "掌厨的脚步踖踖勤，俎上祭肉很丰硕，有的烧有的烤。", "主妇恭谨莫莫，豆中菜肴很丰盛。", "做宾做客，献酬交错往来。", "礼仪都合规矩，笑语都合时宜。", "神保降临了，回报以大福，万寿来酬答！", "我十分敬慎，礼仪没有差错。", "工祝致告辞，前去赏赐孝孙。", "芬芳的孝祀，神灵爱这饮食。", "赐你百福，如期如法。", "既整齐又敏捷，既端正又谨敕。", "永远赐你至福，成万成亿！", "礼仪已完备，钟鼓已戒备，孝孙就位，工祝致告，神都醉了，皇尸起身。", "敲钟送尸，神保归去。", "诸宰和主妇，撤去祭品不迟缓。", "诸父兄弟，一齐私下宴饮。", "乐器都搬入奏响，来安享后得的福禄。", "你的菜肴已进上，无人怨都庆贺。", "既醉又饱，大小都叩首。", "神灵爱这饮食，使君长寿。", "很顺很合时，要把礼节做尽。", "子子孙孙，不要废止要长久奉行！"], "xy-050": ["那绵延的南山，是大禹平治的。", "原野洼地开垦齐整，曾孙在此耕田。", "我划疆界理田亩，南北东西定垄亩。", "上天阴云密布。", "雨雪雰雰下，又加上细雨霡霂。", "既优渥又润泽，既沾湿又充足。", "生长我的百谷。", "田界整齐翼翼，黍稷茂盛彧彧。", "曾孙的收获，用来做酒食。", "献给尸和宾，寿考到万年。", "田中有小屋，田界有瓜。", "剥开腌成菹，献给皇祖。", "曾孙长寿，受天之福。", "祭用清酒，跟上赤色公牛，享祀祖考。", "拿起鸾铃刀，拨开牲毛，取它的血和脂膏。", "冬祭献享，芬芳四溢。", "祀事十分明备。", "先祖来到堂上。", "回报以大福。", "万寿无疆。"], "xy-051": ["那广阔的大田，每年收取上万。", "我取出陈粮，养活我的农人。", "自古就有丰年。", "如今去到南亩，有的除草有的培土。", "黍稷薿薿茂盛，大人止息其间，进用我的英俊之士。", "用我洁净的黍稷，与我祭祀的羊，祭社神祭四方。", "我的田已美好，是农夫的庆贺。", "琴瑟击鼓，迎接田祖。", "祈求甘雨，助成我的稷黍，养育我的男女。", "曾孙到来了，带着他的妇和子。", "送饭到南亩，田官见了很欢喜。", "拉过左右的人，尝尝味道好不好。", "禾苗整治满田亩，又好又丰收。", "曾孙不发怒，农夫能勤敏。", "曾孙的庄稼，如屋茅如车梁堆得高。", "曾孙的粮囤，如小丘如高京。", "于是求千座仓，于是求万辆箱。", "黍稷稻粱，是农夫的庆贺。", "回报以大福，万寿无疆。"], "xy-052": ["大田庄稼多，种子已选农具已备，诸事已就绪。", "用我锋利的耜，开始耕作南亩。", "播种百谷，长得挺直又硕大，曾孙称心如意。", "已抽穗已结壳，已坚实又美好，没有空壳没有莠草。", "除掉螟虫螣虫，还有蟊贼害虫，不要害我田中嫩苗。", "田祖有神灵，把害虫投进炎火。", "阴云萋萋起，雨势祁祁降。", "雨先落我公田，接着及我私田。", "那边有未割的嫩禾，这边有未收的禾把；那边有遗落的禾把，这边有滞留的穗子。", "都成了寡妇的好处。", "曾孙到来了，带着他的妇和子。", "送饭到南亩，田官见了很欢喜。", "前来四方禋祀，用赤牛黑猪，以及黍稷。", "用来献享祭祀，祈求大福。"], "xy-053": ["望那洛水啊，河水泱泱宽广。", "君子到来了，福禄如茅草堆积。", "蔽膝韎韐朱红亮，用来统率六军。", "望那洛水啊，河水泱泱宽广。", "君子到来了，刀鞘玉饰光彩。", "君子万年长寿，保有他的家室。", "望那洛水啊，河水泱泱宽广。", "君子到来了，福禄都汇同。", "君子万年长寿，保有他的家邦。"], "xy-054": ["花儿裳裳盛开，叶子湑湑茂盛。", "我遇见那人，我心畅快舒展。", "我心畅快舒展，因此有美誉安处。", "花儿裳裳盛开，芸芸一片黄。", "我遇见那人，他自有文章法度。", "他自有文章法度，因此有喜庆。", "花儿裳裳盛开，有黄有白。", "我遇见那人，驾着四匹白黑马。", "驾着四匹白黑马，六条缰绳光泽好。", "往左往左，君子都适宜。", "往右往右，君子都具备。", "正因为他具备，所以能继承祖德。"], "xy-055": ["交交叫的桑扈，羽毛有文采。", "君子快乐啊，受天之福。", "交交叫的桑扈，颈毛有文采。", "君子快乐啊，是万邦的屏障。", "是屏障是栋梁，诸侯以他为法度。", "不敛戢不难慎，受福就不多。", "兕角杯弯曲，美酒思柔和。", "与人交往不傲慢，万福来汇聚。"], "xy-056": ["鸳鸯飞啊飞，用网罗来捕。", "君子万年长寿，福禄适宜他。", "鸳鸯停在鱼梁，收起左翅膀。", "君子万年长寿，宜享长远福。", "乘马在马厩，铡草喂料养它。", "君子万年长寿，福禄养护他。", "乘马在马厩，喂料铡草养它。", "君子万年长寿，福禄安抚他。"], "xy-057": ["那高高的皮弁，究竟为了什么？", "你的酒既美，你的肴既好。", "难道是外人吗？", "是兄弟不是别人。", "茑与女萝，攀附在松柏上。", "未见君子，忧心弈弈；既见君子，庶几欢喜。", "那高高的皮弁，究竟期待何时？", "你的酒既美，你的肴合时。", "难道是外人吗？", "兄弟都来了。", "茑与女萝，攀附在松树上。", "未见君子，忧心怲怲；既见君子，庶几有好处。", "那高高的皮弁，戴在头上。", "你的酒既美，你的肴既丰。", "难道是外人吗？", "是兄弟和甥舅。", "如同下雪，先落下的是霰。", "死丧没有定期，相见日子不多。", "今晚饮酒作乐，君子只管宴饮。"], "xy-058": ["车辖间关响啊，想那美少女出嫁啊。", "不是饥不是渴，是美德来相会。", "虽没有很多好友？", "也要宴饮且欢喜。", "靠着那平林，聚集着长尾雉。", "正当年的美女，以美德来教诲。", "宴饮且有美誉，爱你永不厌。", "虽没有美酒？", "也请多少喝一点。", "虽没有嘉肴？", "也请多少吃一点。", "虽没有美德相配？", "愿你来与我同心。", "登上那高冈，砍那柞树当柴。", "砍那柞树当柴，叶子湑湑茂盛。", "难得遇见你，我心畅快舒展。", "高山令人仰望，大道令人遵行。", "四匹公马不停蹄，六条缰绳如琴弦和谐。", "遇见你这新婚，安慰了我的心。"], "xy-059": ["营营飞的青蝇，停在篱笆上。", "和乐平易的君子，不要听信谗言。", "营营飞的青蝇，停在荆棘上。", "谗人没有准则，搅乱四方邦国。", "营营飞的青蝇，停在榛树上。", "谗人没有准则，离间我们二人。"], "xy-060": ["宾客初入筵席，左右秩序井然。", "笾豆排列整齐，菜肴果品陈列。", "酒既醇和甘美，饮酒十分和谐。", "钟鼓已摆好，举杯劝酒从容。", "大靶已竖起，弓箭已拉开。", "射手已会齐，献上你的射功。", "射中那靶心，祈求罚你喝酒。", "籥舞笙鼓，音乐和谐演奏。", "进献娱乐烈祖，以合百礼。", "百礼都到了，盛大又众多。", "赐你大福，子孙尽享安乐。", "安乐又欢喜，各自呈献才能。", "宾客自寻对手，主人又进来陪。", "斟满那大杯，进献合你时宜。", "宾客初入筵席，温温恭敬。", "还未醉时，威仪庄重反反。", "已经醉了，威仪轻浮幡幡。", "离开座位挪动，屡屡起舞仙仙。", "还未醉时，威仪谨慎抑抑。", "已经醉了，威仪失态怭怭。", "这就叫醉了，不知自己的身份秩序。", "宾客既已醉了，又号又闹。", "打乱我的笾豆，屡屡起舞歪歪斜斜。", "这就叫醉了，不知自己的过错。", "歪戴皮弁倾斜，屡屡起舞傞傞不停。", "醉了就出去，大家都受其福。", "醉了还不出去，这就叫败德。", "饮酒很好，只在于有美仪。", "凡此饮酒的人，有醉的有不醉的。", "已设了监酒官，或有史官佐助。", "那醉的不善，不醉的反觉羞耻。", "不要放纵听从，别让大为怠慢。", "不该说的不要说，不该从的不要语。", "顺着醉话乱说，能逼出没角的公羊。", "三杯就不清醒，何况敢再多饮。"], "dy-001": ["文王神灵在上，光辉昭著于天。", "周虽是古老邦国，天命却焕然一新。", "周邦岂不显赫，帝命岂不及时。", "文王升降往来，常在上帝左右。", "勤勉不倦的文王，美名流传不止。", "厚赐恩泽于周，惠及文王子孙。", "文王的子孙本支百代绵延，周朝的士人也世世显荣。", "世代并不显赫的人，做事仍恭谨翼翼。", "多少杰出之士，生在这王国里。", "王国能出人才，正是周邦栋梁；济济多士，文王因此安宁。", "庄严的文王，光明又敬慎。", "伟大啊天命，落到商的子孙身上。", "商的子孙，数目何止亿万。", "上帝已经降命，他们便臣服于周。", "臣服于周，可见天命并不常在一家。", "殷商俊士敏慧，前来京师助祭灌酒。", "他们行灌祭时，仍穿殷人的黼裳戴殷冠。", "王的忠臣啊，难道不思念你们的祖先。", "思念祖先，就要修好自己的德行。", "永远配合天命，自己求取多福。", "殷未失人心时，也能配合上帝。", "应当以殷为鉴，大命得来不易！", "天命不易保，不要败坏在你自己身上。", "显扬美善名声，要想到殷的兴亡皆由天。", "上天行事，无声无息。", "效法文王，万邦才会信服。"], "dy-002": ["人间明察昭著，天上赫赫显耀。", "天命难测可信，为王本非容易。", "天位本属殷嫡，却使他不能号令四方。", "挚国任氏之女，从殷商前来，嫁到周邦，做京师的妇人。", "她匹配王季，专行德义。", "大任有了身孕，生下这位文王。", "就是这位文王，小心翼翼。", "光明事奉上帝，招来许多福泽。", "德行不邪僻，因而承受各方邦国。", "上天俯察下方，天命已经集中。", "文王初年，上天为他作成匹配。", "在洽水之北，在渭水之滨。", "文王嘉美这婚事，大国有好女子。", "大国之女，美如天帝之妹。", "纳聘定下吉祥，亲迎于渭水。", "连舟作桥，婚礼何等光耀。", "天命自天而来，命定这位文王。", "在周在京，续娶莘国之女。", "长子继行正道，诚笃生下武王。", "上天保佑命你，和合征伐大商。", "殷商军队，会聚如林。", "陈兵牧野，唯我周侯兴起。", "上帝看着你们，不要三心二意。", "牧野宽广，檀车闪亮，四马强壮奔腾。", "太师尚父，如鹰扬飞。", "辅佐武王，大举伐商，一朝而天下清明。"], "dy-003": ["瓜瓞绵绵不绝。", "周民初兴，从杜水到漆水一带。", "古公亶父挖窑穴居，还没有房屋家室。", "古公亶父清晨赶马启程。", "沿着西边水涯，来到岐山之下。", "带着姜姓女子，一起来察看居处。", "周原肥沃丰美，苦菜也甜如饴糖。", "于是开始谋划，灼龟问卜，说可住可时，就在这里筑室。", "于是安顿下来，分左右，定疆界治田亩，开沟作垄。", "从西到东，处处有人办事。", "召唤司空司徒，让他们建立家室。", "准绳拉得笔直，夹板筑墙，宗庙庄严翼翼。", "装土声隆隆，投土声轰轰，夯土登登，削墙冯冯。", "百堵墙一齐起来，大鼓也压不住劳动声。", "于是立起皋门，皋门高大。", "于是立起应门，应门严整。", "于是筑起大社，戎众由此出发。", "虽未尽消怒气，也不损美名。", "柞棫拔除干净，道路通畅。", "混夷奔逃，喘息不止！", "虞芮两国来求裁决，文王感动了他们的善心。", "我说有亲附之臣，我说有前后辅弼。", "我说有奔走效力的，我说有抵御外侮的！"], "dy-004": ["棫朴蓬蓬茂盛，砍来堆积作薪。", "庄严的君王，左右之人奔赴跟从。", "庄严的君王，左右捧着玉璋。", "捧璋仪容肃穆，俊士正相宜。", "泾水上舟船疾行，众人齐力划桨。", "周王出征，六军跟随。", "浩瀚天河，成章于天上。", "周王高寿，怎能不培育人才？", "雕琢成文采，内质如金玉。", "勤勉的我王，纲纪四方。"], "dy-005": ["看那旱山山脚，榛楛丛生茂密。", "和乐平易的君子，求福也靠和乐平易。", "玉瓒鲜明，黄酒流在其中。", "和乐平易的君子，福禄降临。", "鸢鸟飞上高天，鱼儿跃入深渊。", "和乐平易的君子，怎能不培育人才？", "清酒已经斟上，赤色公牛已经备好。", "用来享祀，祈求大福。", "柞棫密密，是百姓燎祭所用。", "和乐平易的君子，神灵给予慰劳。", "葛藤蔓延，爬上枝条。", "和乐平易的君子，求福不走邪路。"], "dy-006": ["端庄的大任，文王之母；美好的周姜，王室之妇。", "大姒继承美德声名，于是多子多男。", "惠爱先公，神灵无怨无痛。", "先以身作则于嫡妻，推及兄弟，用以治理家邦。", "宫中和睦，庙中肃敬。", "虽不显赫也如有神临，虽无厌怠也能自保。", "故大难不尽，灾疾不加。", "未闻也合规矩，未谏也能采纳。", "故成人有德，少年有成。", "古人从不厌倦，选拔这些俊士。"], "dy-007": ["伟大啊上帝，俯察下方赫赫威严。", "监察四方，寻求民众安定。", "这两个国家，政治不得人心。", "那四方之国，于是探究度量。", "上帝厌恶他们，憎恶其疆域扩张。", "于是眷顾西方，以此为安居之地。", "砍除屏弃，那些枯死荫蔽之木。", "修治平整，那些灌丛丛生之树。", "开启开辟，那些柽椐之木。", "攘除剔净，那些山桑柘树。", "帝迁明德之人，串夷败逃于路。", "天立匹配之君，受命已经稳固。", "帝察看山岭，柞棫拔除，松柏通直。", "帝建立邦国匹配，从太伯、王季开始。", "这位王季，本性友爱。", "友爱其兄，厚增福庆，赐以光荣。", "受禄不丧失，遍有四方。", "这位王季，帝衡量他的心。", "静其德音，其德能明。", "能明能善类，能长能君。", "为这大邦之王，能顺能亲附。", "至于文王，其德无可悔恨。", "既受帝赐福祉，延及子孙。", "帝对文王说：不要跋扈强梁，不要贪羡，先登上高岸。", "密人不恭顺，敢抗拒大邦，侵阮往共。", "王赫然发怒，整顿军队，阻遏来犯之旅。", "以厚增周的福佑，以应答天下。", "依着京地驻扎，从阮疆进军。", "登上我的高冈，不要陈兵我的山陵。", "我的陵我的阿，不要饮我的泉，我的泉我的池。", "度量那鲜美原野，居岐山之南，在渭水之侧。", "万邦的榜样，下民的君王。", "帝对文王说：我眷念明德，不靠大声厉色，不靠棍棒威逼。", "不识不知，只顺帝的法则。", "帝对文王说：询问你的友邦，会同你的兄弟。", "用你的钩援，与你的临车冲车，去攻打崇国城墙。", "临车冲车从容，崇城高高矗立。", "捉获俘虏连连，割取左耳安然。", "祭天祭马，招致归附，四方因此不敢欺侮。", "临车冲车强盛，崇城高峻。", "于是攻伐出击，于是断绝消灭。", "四方因此不敢违逆。"], "dy-008": ["开始营建灵台，规划又经营。", "百姓来建造，不日就完成。", "开工并不急迫，百姓如子般赶来。", "王在灵囿，母鹿安卧。", "母鹿肥美光泽，白鸟洁白鲜明。", "王在灵沼，满池鱼儿跳跃。", "钟架有崇牙，大鼓与大钟。", "敲击鼓钟有节奏，欢乐在辟雍。", "敲击鼓钟有节奏，欢乐在辟雍。", "鼍鼓咚咚响。", "盲乐师奏起大功之乐。"], "dy-009": ["后嗣有武功的是周，世代有明哲之王。", "三后在天，今王匹配于京。", "王匹配于京，以求世世有德。", "永远配合天命，成就王的诚信。", "王的诚信，是天下的榜样。", "永远怀着孝思，孝思就是法则。", "爱戴这一人，诸侯都顺其德。", "永远怀着孝思，光明啊继承大业。", "光明地引导后来者，继承祖先足迹。", "至于万年，承受天的福佑。", "承受天的福佑，四方前来祝贺。", "至于万年，岂无辅佐之人。"], "dy-010": ["文王有声名，果然大有声名。", "求取安宁，终见成功。", "文王真伟大啊！", "文王受命，有此武功。", "伐崇之后，在丰建邑。", "文王真伟大啊！", "筑城挖壕，作丰与之相配。", "并非急于私欲，而是追思尽孝。", "王后真伟大啊！", "王功昭著，就是丰的城垣。", "四方会同，王后是栋梁。", "王后真伟大啊！", "丰水东流，是大禹的功绩。", "四方会同，皇王是君长。", "皇王真伟大啊！", "镐京有辟雍，从西从东，从南从北，无不心服。", "皇王真伟大啊！", "占卜问王，定居镐京。", "龟卜予以确认，武王完成此事。", "武王真伟大啊！", "丰水有芑草，武王岂不做事业？", "留给子孙谋略，安定辅翼后代。", "武王真伟大啊！"], "dy-011": ["最初生下周民的，是姜嫄。", "生民是怎样的？", "能精诚祭祀，以求去掉无子之忧。", "踩着帝足迹拇指处而心喜，于是歇息，于是怀孕肃敬。", "于是生育养育，就是后稷。", "满了月数，头胎生得顺利如羊羔。", "不裂不破，无灾无害。", "以此显赫其灵异。", "上帝不安宁吗，不享禋祀吗，居然生了孩子。", "把他放在窄巷，牛羊庇护喂养他。", "把他放在平林，恰逢人们伐木。", "把他放在寒冰，鸟儿用翅膀覆盖他。", "鸟儿飞走了，后稷呱呱哭了。", "哭声又长又大，响彻道路。", "他会爬行时，已聪慧有识。", "自己寻求口食。", "种植大豆，大豆茂盛飘扬。", "禾穗垂垂，麻麦浓密，瓜瓞累累。", "后稷种庄稼，有相助之道。", "除去茂草，种下嘉谷。", "种子发芽含苞，苗儿渐长上扬。", "拔节抽穗，籽粒坚实美好。", "穗垂饱满，于是有了邰的家室。", "天降嘉种，有秬有秠，有穈有芑。", "遍种秬秠，收割堆在田亩。", "遍种穈芑，扛着背着。", "带回家开始祭祀。", "我们的祭祀怎样？", "有的舂有的舀，有的簸有的蹂。", "淘米声叟叟，蒸饭气浮浮。", "于是谋划思量。", "取艾蒿和祭脂，取公羊祭路神，又烧又烤，以求来年兴旺。", "我盛在豆里，在豆在登。", "香气开始上升，上帝安然来享。", "这香气多么适时。", "后稷开创祭祀。", "庶几无罪无悔，一直传到如今。"], "dy-012": ["道旁芦苇丛生，牛羊不要践踏。", "正含苞正成形，叶子润泽柔软。", "亲近的兄弟，不要疏远都来近前。", "有的摆开筵席，有的授给几案。", "摆筵设席，授几有侍者相继。", "有的献酒有的回敬，洗爵放斝。", "肉酱荐上，有的烧有的烤。", "佳肴有脾有口腮，有的唱歌有的击鼓。", "雕弓已坚，四箭已匀，发矢已均，按贤能排宾客。", "雕弓已拉满，已挟着四箭。", "四箭如树栽立，排宾不以轻侮。", "曾孙是主人，酒醴醇厚，用大斗斟酒，祈求黄发高寿。", "黄发驼背的老人，前导又扶持。", "高寿是吉祥，以助大福。"], "dy-013": ["已经醉于酒，已经饱于德。", "君子万年，赐你大福。", "已经醉于酒，你的菜肴已备好。", "君子万年，赐你光明。", "光明融融，高朗得善终，善终又有新开端。", "公尸美好致辞。", "他的话是什么？", "笾豆洁净美好。", "朋友相辅助，辅助以威仪。", "威仪很合时宜，君子有孝子。", "孝子不匮乏，永远赐你同类。", "那同类是什么？", "室家和美周遍。", "君子万年，永远赐福给后嗣。", "那后嗣是什么？", "天覆盖你以禄位。", "君子万年，大命有附属。", "那附属是什么？", "赐你贤淑女子。", "赐你贤淑女子，随带着子孙。"], "dy-014": ["野鸭鸥鸟在泾水，公尸来宴来安宁。", "你的酒已清，你的菜已香。", "公尸宴饮，福禄来成全。", "野鸭鸥鸟在沙滩，公尸来宴来适宜。", "你的酒已多，你的菜已美。", "公尸宴饮，福禄来助。", "野鸭鸥鸟在沙洲，公尸来宴来安处。", "你的酒已滤清，你的菜是干肉。", "公尸宴饮，福禄降下。", "野鸭鸥鸟在水流会合处，公尸来宴来尊崇，既宴于宗庙，福禄便降临。", "公尸宴饮，福禄更加崇厚。", "野鸭鸥鸟在峡口，公尸到来和悦欣欣。", "美酒欣欣，燔炙芬芳。", "公尸宴饮，往后没有艰难。"], "dy-015": ["嘉美和乐的君子，显赫有美德。", "宜于民宜于人，从天受禄。", "保佑任命他，从天申明。", "求禄得百福，子孙千亿。", "穆穆皇皇，宜为君宜为王。", "不犯错不忘本，遵循旧有章程。", "威仪严密，德音有条理。", "无怨无恶，遵循群臣匹偶。", "受福无疆，是四方的纲领。", "有纲有纪，安及朋友。", "百位诸侯卿士，爱戴天子。", "在位不懈怠，是民所安息之处。"], "dy-016": ["忠厚的公刘，不苟安不偷闲。", "定田界定疆界，积蓄入仓；包裹干粮，装进橐囊。", "想着和辑光耀，弓矢张开；干戈斧钺扬起，于是启程。", "忠厚的公刘，察看这片原野。", "既人多又繁盛，既和顺又舒畅，没有长叹。", "登上小山，又下到平原。", "用什么佩带？", "是玉和瑶，刀鞘饰玉的佩刀。", "忠厚的公刘，前往那百泉。", "眺望广阔原野，登上南冈。", "于是看见京地，京师的原野。", "于是安居，于是寄住，于是说说，于是谈谈。", "忠厚的公刘，在京地依托。", "步履整齐济济，使人设筵设几。", "登上座位依靠，于是祭告群神。", "从猪圈捉猪，用匏瓢斟酒。", "给他吃给他喝，奉他为君为宗。", "忠厚的公刘，土地既广又长。", "测日影登冈，察看阴阳面，观察流泉。", "军队分三批轮换，度量低湿与平原。", "治田收粮，度量西山夕阳之地。", "豳地居所确实宽广。", "忠厚的公刘，在豳建馆舍。", "渡渭水横渡，取磨石锻石，基地于是整理。", "于是人众物有，夹着皇涧居住。", "溯着过涧而上。", "住众于是密集，往水湾曲处靠近。"], "dy-017": ["远远舀取那路旁积水，挹来注到这里，可以蒸饭。", "和乐平易的君子，是民的父母。", "远远舀取那路旁积水，挹来注到这里，可以洗涤酒器。", "和乐平易的君子，是民所归附。", "远远舀取那路旁积水，挹来注到这里，可以洗涤溉清。", "和乐平易的君子，是民所安息。"], "dy-018": ["有曲折的山阿，旋风从南边来。", "和乐平易的君子，来游来歌，陈说他的心声。", "你优游啊畅游啊，你悠闲啊休息啊。", "和乐平易的君子，使你尽其天年，像先公那样善终。", "你的疆土版图，也十分广大厚实。", "和乐平易的君子，使你尽其天年，百神以你为主。", "你受命长久了，福禄使你安康了。", "和乐平易的君子，使你尽其天年，大福常伴随你。", "有依凭有羽翼，有孝有德，来引导来辅佐。", "和乐平易的君子，四方以为法则。", "仪表堂堂昂扬，如圭如璋，美名美望。", "和乐平易的君子，四方以为纲领。", "凤凰在飞，羽声翙翙，也聚集停歇。", "王有众多吉士济济，供君子驱使，爱戴天子。", "凤凰在飞，羽声翙翙，也高飞附天。", "王有众多吉人济济，听从君子之命，爱抚庶民。", "凤凰鸣叫了，在那高冈上。", "梧桐生长了，在那朝阳处。", "枝叶菶菶萋萋，凤鸣雍雍喈喈。", "君子的车子，又多又众。", "君子的马，既熟练又善驰。", "陈诗并不多，只为成此歌。"], "dy-019": ["百姓也劳苦了，差不多可以稍稍安康。", "加恩于这中国，以安定四方。", "不要放纵狡诈顺从之人，以谨防不良之辈。", "遏止寇虐，他们竟不畏法度昭明。", "怀柔远方亲善近处，以安定我王。", "百姓也劳苦了，差不多可以稍稍休息。", "加恩于这中国，以为民的聚合。", "不要放纵狡诈顺从之人，以谨防喧扰昏乱。", "遏止寇虐，不要使百姓忧愁。", "不要抛弃你的功劳，以成王的美善。", "百姓也劳苦了，差不多可以稍稍喘息。", "加恩于这京师，以安定四国。", "不要放纵狡诈顺从之人，以谨防行为无极。", "遏止寇虐，不要让他们作恶。", "敬慎威仪，以亲近有德之人。", "百姓也劳苦了，差不多可以稍稍歇息。", "加恩于这中国，使民忧得以宣泄。", "不要放纵狡诈顺从之人，以谨防丑恶暴厉。", "遏止寇虐，不要使正道败坏。", "你虽是年轻人，作用却很弘大。", "百姓也劳苦了，差不多可以稍稍安宁。", "加恩于这中国，使国中没有残害。", "不要放纵狡诈顺从之人，以谨防纠缠固结。", "遏止寇虐，不要使正道颠倒。", "王啊我想成全你，因此大声进谏。"], "dy-020": ["上帝反常乖戾，下民尽皆病苦。", "说出的话不对，谋划也不长远。", "目无圣人而自恣。", "不忠厚诚实。", "谋划还不长远，因此大声进谏。", "天正降难，不要那样喜乐洋洋。", "天正动荡，不要那样泄沓多言。", "言辞和辑了，民就融洽了。", "言辞和悦了，民就安定了。", "我虽职务不同，与你同为同僚。", "我来与你商议，你听我却傲慢嚣嚣。", "我的话是切实的，不要当作笑话。", "先民有言，要询问割草打柴的人。", "天正暴虐，不要那样戏谑。", "老夫恳恳诚恳，小子却骄蹇自得。", "不是我说话老迈，是你拿忧患当戏谑。", "多行将如火炽烈，不可救药。", "天正愤怒。", "不要柔媚屈从。", "威仪尽皆迷乱，善人如尸般不作为。", "民正痛苦呻吟，难道无人敢猜测时势？", "丧乱耗尽资财，竟无人恩惠我众？", "天诱导民，如埙如篪相和，如璋如圭相合，如取如携般容易。", "携取不必说增益，诱导民很容易。", "民已多邪僻，不要自己再立邪法。", "善人是藩篱，大众是垣墙，大邦是屏障，大宗是栋梁，怀德则安宁，宗子是城池。", "不要使城毁坏，不要独自陷入畏惧。", "敬畏天的怒，不敢戏豫。", "敬畏天的变，不敢放纵驰驱。", "昊天说是明亮，与你一同出入为王。", "昊天说是旦明，与你一同游逛放纵。"], "dy-021": ["荡荡的上帝，是下民的君长。", "暴厉的上帝，其命多邪僻。", "天生众民，其命不可全信。", "无不有开端，很少能有善终。", "文王说咨嗟，咨嗟你这殷商。", "竟然这样强横？", "竟然这样聚敛克剥？", "竟然这样在位？", "竟然这样在职？", "天降傲慢之德，你却用力助长。", "文王说咨嗟，咨嗟你这殷商。", "你若任用善类，强横者就多怨恨。", "用流言应对。", "寇盗攘夺在朝内。", "又诅咒又祝祷，没完没了。", "文王说咨嗟，咨嗟你这殷商。", "你在中国咆哮逞威。", "把招来的怨恨当作德。", "你德不明，于是无背无侧之臣。", "你德不明，因而无陪无卿。", "文王说咨嗟，咨嗟你这殷商。", "天没有让你沉湎于酒，不义之事却跟从效法。", "你的仪容举止已经过失。", "不分白天黑夜。", "又喊又叫。", "把白昼当作黑夜。", "文王说咨嗟，咨嗟你这殷商。", "如蝉如螗嘈杂，如沸如羹翻腾。", "大小近于丧亡，人们还照样行事。", "对内激怒中国，延伸到鬼方。", "文王说咨嗟，咨嗟你这殷商。", "不是上帝不好，是殷不用旧法。", "虽无老成之人，还有典章刑律。", "竟然无人听从，大命因此倾覆。", "文王说咨嗟，咨嗟你这殷商。", "人也有话说：树倒根揭出，枝叶还未受害，根本却先拔断。", "殷的鉴戒不远，就在夏后之世。"], "dy-022": ["严密的威仪，是德的方正边角。", "人也有话说：没有哲人不显得愚，庶人的愚，也只是本分的毛病。", "哲人显得愚，却是触犯常理。", "最强的是得人，四方都会训法他。", "有正直的德行，四国都会顺从。", "大谋定命，远虑按时宣告。", "敬慎威仪，是民的准则。", "到了如今，却迷乱于政事。", "颠覆其德，沉湎于酒。", "你虽从于耽乐，却不念继承之业。", "不广求先王之道，以执守明法。", "故皇天不佑，如那泉水流逝，不要相率沦亡。", "早起晚睡，洒扫庭内，是民的表章。", "修好车马，弓矢兵器，用以戒备战事，用以远拒蛮方。", "安定你的人民，谨守你的法度，用以戒备意外。", "谨慎你的出言，敬重你的威仪，无不柔和美善。", "白圭的污点，还可以磨掉；这话的污点，却不可挽回！", "不要轻易发言，不要说苟且即可，无人按住我的舌，话一出就追不回。", "没有话不受回应，没有德不受报答。", "惠爱朋友，以及庶民小子。", "子孙谨慎相续，万民无不奉承。", "看你结交君子，和柔你的容颜，庶几没有过失。", "察看你在室内，尚且无愧于屋漏之神。", "不要说不显眼，无人看见我。", "神的降临，不可测度，何况可以厌怠！", "修明你的德，使之善使之美。", "好好谨慎你的举止，不愆于礼仪。", "不僭越不贼害，很少不成为准则。", "别人投我以桃，我报之以李。", "那童羊却长角，实在惑乱小子。", "柔韧的好木，安上丝弦。", "温温恭谨之人，是德的根基。", "若是哲人，告诉他善言，就顺德而行。", "若是愚人，反说我僭越。", "民各有各的心思。", "唉呀小子，还不知好坏。", "不只用手携着你，还用话指示事理。", "不只当面命令你，还提着你的耳朵说。", "假说你还无知，可你也已经抱子了。", "人若不自满，谁能早知而晚成？", "昊天很昭明，我活着却无乐。", "看你昏昏昧昧，我心惨惨忧伤。", "教诲你谆谆，你听我却藐藐。", "不用作教导，反用作暴虐。", "假说你还无知，也已经算年迈了。", "唉呀小子，告诉你旧有的法度。", "听用我的谋划，庶几没有大悔恨。", "天正艰难，将要丧其国。", "取譬并不远，昊天不会差错。", "邪僻其德，使民大大困急。"], "dy-023": ["茂盛那柔桑，树下阴凉均匀，捋采使它稀疏，病害这下民。", "心忧不断，凄凉怅惘填满啊。", "浩大的昊天，难道不可怜我？", "四马强壮，旌旗翩翩。", "乱生不平息，无国不混乱。", "民中无存壮丁，都遭祸成灰烬。", "唉呀有哀，国运如此危急。", "国运耗尽资财，天不扶助我。", "无处可停驻，说去又能往哪里？", "君子所思，存心不争竞。", "谁生出祸端，至今仍为病梗？", "忧心殷殷，思念我的土宇。", "我生不逢时，遇上天大怒。", "从西到东，无处可安处。", "我多见病苦，边疆十分危急。", "若谋划谨慎，乱况就会削减。", "告诉你忧恤，教你序定爵位。", "谁能手握热物，却不去用水洗？", "那怎能向善，只会相率溺亡。", "如那逆风而行，也很窒息难喘。", "民有上进心，却被阻遏达不到。", "喜好这稼穑，用力于民代耕而食。", "稼穑才是宝，代食难道好？", "天降丧乱，灭我拥立之王。", "降下这些蟊贼，庄稼尽皆受害。", "哀痛中国，都连缀以至于荒芜。", "没有余力，来顾念苍天。", "这位惠爱之君，是民人所瞻仰。", "存心宣明谋略，考察慎选辅相。", "那位不顺者，独自以为善。", "自有一套肺肠，使民尽皆狂乱。", "看那林中，鹿儿成群。", "朋友已相谮毁，不以善相助。", "人也有话说：进退都陷于困境。", "这位圣人，眼光能看百里。", "那位愚人，反而狂喜。", "不是不能说，为何这般畏忌？", "这位良人，不求进不钻营。", "那位忍心之人，却被顾念反复任用。", "民之贪乱，宁可自取荼毒。", "大风有通道，空旷在大谷。", "这位良人，行事合于善。", "那位不顺者，行于污垢之中。", "大风有通道，贪人败坏同类。", "顺耳的话就应答，劝谏的话如醉不听。", "不用其良言，反使我悖乱。", "唉你们朋友，我岂不知而作此歌。", "如那飞鸟，有时也被射获。", "既已荫覆你们，反来威吓我。", "民之无极，专事刻薄善背叛。", "做不利民之举，还唯恐不能。", "民之邪僻，专竞用力作恶。", "民尚未安定，专做盗寇之事。", "诚恳说不可，反背后大骂。", "虽说不是针对我，我已作了这首歌！"], "dy-024": ["浩大的天河，光辉回转于天。", "王说：唉呀！", "今日之人有何罪过？", "天降丧乱，饥馑一再到来。", "无神不祭祀，不吝惜牺牲。", "圭璧已经用尽，难道还不听我？", "旱情已经太甚，郁热隆隆如虫鸣。", "禋祀不断，从郊祭到宫庙。", "上下奠酒埋玉，无神不尊崇。", "后稷不能救，上帝不降临。", "耗损败坏下方土地，难道正落到我身上。", "旱情已经太甚，不可推开。", "兢兢业业，如霆如雷。", "周剩余的黎民，几乎没有孑遗。", "昊天上帝，就不留给我。", "为何不相畏惧？", "先祖也将毁摧。", "旱情已经太甚，不可阻遏。", "赫赫炎炎，不可熄灭。", "自己哀伤，怎能说还能得福？", "大命将近终结，无人瞻仰顾念。", "群公先正之神，就不帮助我。", "父母先祖，为何忍心对我？", "旱情已经太甚，山川一片光秃。", "旱魃肆虐，如燎如焚。", "我心畏暑，忧心如熏烤。", "群公先正，就不听我。", "昊天上帝，难道要使我逃遁？", "旱情已经太甚，勉力敬畏求去旱。", "为何用旱来病我？", "竟不知缘故。", "祈年很早，祭方社也不晚。", "昊天上帝，就不佑助我。", "恭敬事明神，应当无悔无怒。", "旱情已经太甚，离散无友纪。", "困穷啊众官长，忧病啊冢宰。", "趣马师氏，膳夫左右。", "无人不周济。", "不能止住旱灾，仰望昊天，心里如何安放！", "仰望昊天，星光嘒嘒。", "大夫君子，昭告感通不要松懈。", "大命将近，不要抛弃已成之功。", "所求并非为我自己。", "而是安定众官长。", "仰望昊天，何时惠赐安宁？"], "dy-025": ["高大的岳山，峻极于天。", "岳山降下神灵，生下甫侯和申伯。", "申伯与甫侯，是周的栋梁。", "四国以为藩篱。", "四方得以宣畅。", "勤勉的申伯，王让他继承事业。", "在谢地建邑，作南国的榜样。", "王命召伯，定下申伯的宅第。", "成就这南邦，世代执掌其功。", "王命申伯，作南邦的榜样。", "依靠谢地之人，建造你的城墙。", "王命召伯，治理申伯的土田。", "王命傅御，迁徙他的家臣。", "申伯的功业，由召伯经营。", "城墙开始建造，寝庙已经落成。", "落成后雄伟深远，王赏赐申伯。", "四马骄健，钩膺鲜明。", "王遣送申伯，路车与乘马。", "我考虑你的居所，没有比南土更好。", "赐你大圭，作为你的宝物。", "去吧王舅，南土由你保有。", "申伯真的启程，王在郿地饯行。", "申伯回南方，诚心归往谢邑。", "王命召伯，划定申伯疆界。", "备好粮食，使他速行。", "申伯威武，已经进入谢邑。", "步卒车御安闲。", "周邦都欢喜，有了好栋梁。", "显赫的申伯，王的大舅，文武都是典范。", "申伯之德，柔惠而又正直。", "安抚这万邦，闻名于四国。", "吉甫作此颂，诗意很宏大。", "曲调很好，用来赠给申伯。"], "dy-026": ["天生众民，有事物有法则。", "民秉持常性，喜好这美德。", "天监察有周，光明感通于下。", "保佑这天子，生下仲山甫。", "仲山甫之德，柔美嘉善是准则。", "仪容好脸色好，小心翼翼。", "以古训为法式。", "努力于威仪。", "天子顺从他，明命使他颁布。", "王命仲山甫，作百位诸侯的榜样，继承你祖考，保护王身。", "出纳王命，是王的喉舌。", "颁布政令于外，四方于是响应。", "肃肃的王命，仲山甫执行它。", "邦国好坏，仲山甫明察它。", "既明哲又智慧，用以保全自身。", "早晚不懈怠，以事奉一人。", "人也有话说，软的就吃下，硬的就吐出。", "唯有仲山甫，软的也不吃，硬的也不吐。", "不欺侮鳏寡，不畏惧强横。", "人也有话说，德轻如毛，民很少能举起它。", "我揣度思量，唯有仲山甫能举起。", "爱他却无人能助他。", "衮衣之职有缺失，唯仲山甫能补上。", "仲山甫出行祭路神。", "四马高大。", "征夫敏捷，常恐不及。", "四马奔腾，八铃锵锵。", "王命仲山甫，去东方筑城。", "四马强壮，八铃喈喈。", "仲山甫往齐，盼他速归。", "吉甫作此颂，和穆如清风。", "仲山甫长怀远念，用以慰藉其心。"], "dy-027": ["梁山高大，是禹所治理，道路宽广。", "韩侯受命，王亲自任命：继承你祖考，不要废弃我的命令。", "早晚不懈怠，虔诚恭守你的职位，我的命令不可改易。", "匡正不来朝之方，以辅佐你的君。", "四马高大，很长又壮。", "韩侯入朝觐见，带着大圭，入觐于王。", "王赐韩侯：美旗绶章，竹席车蔽错衡，黑袍红鞋，钩膺镂马额，革蔽浅毛皮，辔革金环。", "韩侯出行祭路，出宿于屠地。", "显父为他饯行，清酒百壶。", "菜肴是什么？", "炖鳖鲜鱼。", "蔬菜是什么？", "是笋和蒲。", "赠品是什么？", "乘马与路车。", "笾豆丰盛。", "诸侯们宴乐。", "韩侯娶妻，是汾王的外甥女，蹶父的女儿。", "韩侯亲迎，到蹶父的里巷。", "百辆车彭彭，八铃锵锵，光耀显赫。", "众娣随嫁，祁祁如云。", "韩侯回头看，光彩盈门。", "蹶父很勇武，没有哪国不到。", "为韩姞择婿，没有比韩更安乐。", "韩土很安乐，川泽广大，鲂鱮肥美，母鹿成群，有熊有罴，有猫有虎。", "庆幸有了好居所，韩姞安乐有誉。", "那广大的韩城，是燕师所筑完。", "因先祖受命，统领这些百蛮。", "王赐韩侯，追族与貊族。", "遍受北国，因此为他们的伯长。", "筑城挖壕，治亩定籍。", "进献貔皮，赤豹黄罴。"], "dy-028": ["江汉水势浮浮，武士气势滔滔。", "不为安不为游，为求讨淮夷而来。", "已出我车，已设我旗。", "不为安不为舒缓，淮夷前来陈兵进逼。", "江汉浩浩汤汤，武士威武洸洸。", "经营四方，向王报告成功。", "四方已经平定，王国庶几安定。", "这时没有争战，王心于是安宁。", "在江汉之滨，王命召虎：开辟四方，治理我疆土。", "不为病害不为急迫，使王国成为准则。", "划疆治理，直到南海。", "王命召虎：来巡视来宣示。", "文武王受命时，召公是栋梁。", "不要说我是小子，要效法召公。", "迅速敏于大事，因此赐你福祉。", "赐你圭瓒，秬鬯一卣。", "祭告有文德的先祖，赐山土田。", "在周受命，从召祖之命，虎拜稽首：天子万年！", "虎拜稽首，称扬王的美善。", "作召公的成器铭：天子万寿！", "明明天子，美名不止，布其文德，协和这四国。"], "dy-029": ["赫赫又明明。", "王命卿士，南仲是太祖，太师是皇父。", "整顿我六军，修治我兵器。", "既敬慎又戒备，加恩于这南国。", "王对尹氏说，命程伯休父，左右陈列队列。", "告戒我师旅，沿着淮浦，巡察这徐土。", "不滞留不耽搁，三事都已就绪。", "赫赫高大，有威严的天子。", "王徐缓安行，不迟缓不游逸。", "徐方连续骚动，震惊了徐方。", "如雷如霆，徐方震惊。", "王奋起武威，如震如怒。", "进用虎臣，怒吼如啸虎。", "陈兵敦厚于淮滨，一再捉获丑虏。", "截断那淮浦，是王师所在。", "王旅众盛啴啴，如飞如高鸟。", "如江如汉，如山的根基。", "如川的奔流，绵绵又整肃。", "不可测不可胜，大举征伐徐国。", "王的谋略确实充实，徐方已经来归。", "徐方已经会同，是天子的功劳。", "四方已经平定，徐方来到王庭。", "徐方不再违逆，王说可以还归。"], "dy-030": ["仰望昊天，却不惠爱我。", "很久不安宁，降下这大灾厉。", "邦国没有安定，士民不得聚敛安居。", "蟊贼为害如病，没有平息终止。", "罪网不收起，没有平复痊愈。", "别人有土田，你反而占有。", "别人有民人，你反而夺去。", "这人该无罪，你反而收捕。", "那人该有罪，你反而开脱。", "哲夫成就城邦，哲妇倾覆城邦。", "美啊那哲妇，实为枭为鸱。", "妇人有长舌，是灾厉的阶梯。", "乱并非降自天，生自妇人。", "不听教不听诲，只亲近妇人宦寺。", "穷究人而忌刻变诈。", "谮毁始于争竞背后。", "难道说还不够极？", "为何作恶？", "如商贾求三倍之利，君子识破这个。", "妇人不管公事，却停止蚕织。", "天为何责罚？", "为何神不赐福？", "舍弃你的大狄之患，却忌恨我。", "不善不祥，威仪不像样。", "贤人说是丧亡了，邦国病困殆尽。", "天降罗网，已经很优厚了。", "贤人说是丧亡了，心里忧愁啊。", "天降罗网，已经很危急了。", "贤人说是丧亡了，心里悲伤啊。", "喷涌的槛泉，是那样深啊。", "心里的忧愁，难道从今天才开始？", "不在我之先，不在我之后。", "高远的昊天，无不能巩固。", "不要有辱皇祖，以拯救你的后代。"], "dy-031": ["旻天暴厉威猛，天重重降下丧乱。", "用饥馑病我，民尽皆流亡。", "我的居处边疆尽皆荒芜。", "天降罪网，蟊贼内讧。", "昏乱谗害不供职，溃乱邪僻，实在想倾覆我邦。", "欺诬诽谤，竟不知自己的污点。", "兢兢业业，很久不安宁，我的职位很贬损。", "如那年旱，草不茂盛，如那浮水枯草。", "我看这邦国，无不溃乱而止。", "往昔的富足比不上那时。", "今日的病苦却比现在更糟。", "那些吃粗粮的反吃细米，为何不自己引退？", "反而更加延长这种局面。", "池水枯竭了，不是说从水滨开始。", "泉水枯竭了，不是说从中间开始。", "这祸害普遍了，反而更加扩大，灾害落到我身上。", "昔日先王受命，有如召公，日辟国百里，如今却日缩国百里。", "唉呀哀哉！", "如今的人，不崇尚有旧德的人。"], "song-001": ["啊庄严清庙，肃穆和雍的显贵助祭。", "济济多士，秉持文王之德。", "称扬在天之灵，敏疾奔走在庙中。", "光明又承继，使人永不厌怠。"], "song-002": ["上天之命，啊庄严运行不已。", "啊多么显赫，文王之德纯一。", "嘉美溢润我，我来收受它。", "大力顺惠我文王，曾孙诚笃奉行。"], "song-003": ["清明又光明，是文王的典法。", "开始禋祀，终至有成，是周的祥祯。"], "song-004": ["有功烈文德的诸侯，赐下这福祉。", "惠爱我无疆，子孙保有它。", "不要在你邦大行罪恶，王将尊崇你。", "思念这些大功，继承序次而光大它。", "最强在于得人，四方都会训法。", "最显在于德，百位诸侯都会效法。", "唉呀，前王不可忘！"], "song-005": ["天造作高山，太王开垦它。", "他开创了，文王安康它。", "他们前往了，岐山有平易道路，子孙保有它。"], "song-006": ["昊天有既定之命，二后承受它。", "成王不敢安逸，早晚以宽密奠定天命。", "啊光明啊！", "尽其一心，于是安定天下。"], "song-007": ["我烹煮我献享，是羊是牛，愿天佑助。", "效法文王的典法，日日安定四方。", "伟大的文王，已经佑助来享。", "我早晚敬畏天威，于是保有它。"], "song-008": ["按时巡行邦国，昊天以之为子，确实佑助有周。", "稍加震威，无不震恐。", "怀柔百神，以及河与高山，真王是君后。", "明昭有周，按序安排在位者。", "收起干戈，装好弓矢。", "我求美德，布陈于这华夏，真王保有它。"], "song-009": ["强毅的武王，没有比他功烈更强。", "显赫的成康，上帝予以嘉美。", "从成康以来，遍有四方，明察纤细。", "钟鼓喤喤，磬管将将，降福穰穰。", "降福大大，威仪慎重。", "既醉既饱，福禄来回报。"], "song-010": ["想到有文德的后稷，能配合那上天。", "安定我众民，无非你的准则。", "留给我们小麦大麦，帝命普遍养育，不分此疆彼界。", "陈布常道于这华夏。"], "song-011": ["啊啊臣工们，敬慎你们的公务。", "王赐你们成法，前来咨询商议。", "啊啊农官，正是暮春，又有何求？", "新田畲田怎样耕种？", "啊美好的麦子，将要接受光明收成。", "明昭上帝，终赐康年。", "命令我众人：收起你们的锹锄，同去看收割。"], "song-012": ["啊嘻成王，已经昭告感通你们。", "率领这些农夫，播种百谷。", "大力开发你们私田，终至三十里。", "也从事你们耕种，上万成对并耕。"], "song-013": ["白鹭振翅飞，在那西边辟雍。", "我的客人到来，也已安集。", "我的客人到来，也已安集。", "在彼无人厌恶，在此无人厌怠。", "庶几早晚勤勉，以永保终誉。"], "song-014": ["丰年多黍多稻，也有高大粮仓，万亿到秭。", "做成酒做成醴，进献给祖妣。", "以配合百礼，降福很普遍。"], "song-015": ["有盲乐师有盲乐师，在周的庭中。", "设立钟架磬架，崇牙上插羽。", "小鼓大鼓悬鼓，鼗磬柷圉齐备。", "既备好便演奏，箫管一齐举起。", "声音喤喤，肃雍和鸣，先祖来听。", "我的客人到来，长久观看成功。"], "song-016": ["美啊漆水沮水，深潜有很多鱼。", "有鳣有鲔，鲦鲿鰋鲤。", "用来享用来祀，以助大福。"], "song-017": ["来时和和雍雍，到达肃肃恭敬。", "助祭的是诸侯，天子穆穆庄严。", "啊进献大牲，助我陈列祭祀。", "伟大啊皇考！", "安定我这孝子。", "明哲的是贤人，文武兼备的是君后。", "安及皇天，能昌盛其后嗣。", "赐我眉寿，助以多福，既佑助烈考，也佑助文母。"], "song-018": ["初次朝见君王，说是求取典章。", "龙旗阳阳鲜明，和铃央央作响。", "辔革有饰，美有烈光。", "率领朝见昭考，以尽孝以献享。", "以助眉寿，永远保有，愿皇多福。", "有功烈文德的诸侯，安以多福，使光明至于大福。"], "song-019": ["有客有客，马也是白色。", "随从萋萋众多，雕琢其旅众。", "有客住一夜，有客住两夜。", "给他绊绳，绊住他的马。", "前去追送他，左右安抚他。", "既有盛大威仪，降福很平易。"], "song-020": ["啊伟大的武王！", "没有比他功烈更强。", "确实有文德的文王，能开创其后嗣。", "嗣子武王承受，战胜殷遏止杀戮，终成你的功业。"], "song-021": ["可怜我这小子，家门遭不幸，孤独在病痛中。", "啊皇考，永世能尽孝。", "思念这皇祖，升降在庭中。", "我这小子，早晚敬慎。", "啊皇王，继承序次思念不忘。"], "song-022": ["咨询我开始执政，遵循这昭考。", "啊悠远啊，我还没有阅历。", "帮我去就近他，继续谋划分散的事务。", "我这小子，不堪家中多难。", "继承上下在庭，升降于其家。", "美啊皇考，以保明其身。"], "song-023": ["敬慎啊敬慎，天是显明的，天命不易保啊。", "不要说高高在上，升降其臣士，每日监察在此。", "我这小子，不够聪明敬慎。", "日有所成月有所进，学问积渐至于光明。", "辅我担当重任，指示我显明的德行。"], "song-024": ["我要惩戒，谨慎防后患。", "无人牵引蜂来，是自己求取辛螫。", "开始只是那鹪鹩，翻飞却成大鸟。", "不堪家中多难，我又陷于辛苦。"], "song-025": ["又除草又砍树，耕得土松泽泽。", "千对并耕除草，往低地往田埂。", "有家长有长子，有弟侄有众徒，有强劳有雇工。", "送饭声嗿嗿，美那送饭妇，亲那耕田汉。", "锋利那犁头，开始耕南亩，播种百谷。", "种子含生气，驿驿破土出。", "特出的苗肥美，苗齐齐匀匀，不停地耘苗。", "收割济济众多，堆积充实，万亿到秭。", "做成酒做成醴，进献给祖妣，以配合百礼。", "香气飶飶。", "是邦家的光荣。", "椒香馨香，老人得安宁。", "不只此刻有此刻，不只今日是今日，从古就是这样。"], "song-026": ["锋利的好犁，开始耕南亩。", "播种百谷，种子含生气。", "有人来看你们，提着筐和莒，送来的是黍饭。", "斗笠是草编，锄头很锋利，用来薅除荼蓼。", "荼蓼朽烂了，黍稷茂盛了。", "收割挃挃响，堆积栗栗密。", "高如城墙，密如梳齿。", "以此打开百室。", "百室装满了，妇子安宁了。", "杀这黄牛，双角弯曲。", "以继承以接续，接续古之人。"], "song-027": ["丝衣鲜明洁净，戴弁恭敬。", "从堂到阶基，从羊到牛，大鼎小鼎，兕觥弯曲。", "美酒柔和。", "不大声不傲慢，是老人的福祥。"], "song-028": ["啊辉煌的王师，遵循养晦待时。", "时运纯然光明了，因此大大佑助。", "我荣受它，矫健是王的造就。", "于是有后嗣任用，实在以你周公为效法的公师。"], "song-029": ["安定万邦，屡获丰年。", "天命不懈怠，桓桓的武王。", "保有其士众，用以经营四方，能安定其家。", "啊昭著于天，皇天以他取代殷。"], "song-030": ["文王已经勤劳了，我应当承受。", "布陈此业连续思念，我前往只求安定。", "这是周的天命，啊要连续思念。"], "song-031": ["啊伟大这周！", "登上那高山，小山与高岳，确实规划会合河神。", "普天之下，聚集此时对扬。", "这是周的天命。"], "song-032": ["肥壮的公马，在远郊野地。", "说起这些马，有驈有皇，有骊有黄，驾车彭彭有力。", "思虑无疆，想到马这样好。", "肥壮的公马，在远郊野地。", "说起这些马，有骓有駓，有骍有骐，驾车伾伾强壮。", "思虑无期，想到马这样有才。", "肥壮的公马，在远郊野地。", "说起这些马，有驒有骆，有骝有雒，驾车绎绎跑不停。", "思虑无厌，想到马这样奋起。", "肥壮的公马，在远郊野地。", "说起这些马，有骃有騢，有驔有鱼，驾车祛祛强健。", "思虑无邪，想到马这样远行。"], "song-033": ["有肥马有肥马，肥那四匹黄马。", "早晚在公所，在公所明察办事。", "鹭羽振振，鹭落下。", "鼓声咽咽，醉了起舞。", "一起欢乐啊！", "有肥马有肥马，肥那四匹公马。", "早晚在公所，在公所饮酒。", "鹭羽振振，鹭在飞。", "鼓声咽咽，醉了归去。", "一起欢乐啊！", "有肥马有肥马，肥那四匹青马。", "早晚在公所，在公所宴饮。", "从今开始，岁岁丰收。", "君子有善禄，留给孙子。", "一起欢乐啊！"], "song-034": ["快乐啊泮水，来采那芹菜。", "鲁侯到来，观看他的旌旗。", "旌旗茷茷飘扬，鸾铃声哕哕。", "无论小大，跟随公出行。", "快乐啊泮水，来采那水藻。", "鲁侯到来，他的马骄健。", "他的马骄健，他的声音昭昭。", "和颜又带笑，不是发怒而是教导。", "快乐啊泮水，来采那莼菜。", "鲁侯到来，在泮宫饮酒。", "既饮美酒，永赐不老。", "顺着那长道，屈服这些群丑。", "穆穆的鲁侯，敬明其德。", "敬慎威仪，是民的准则。", "确实有文确实有武，昭告感通烈祖。", "无不孝敬，自己求取这福。", "明明的鲁侯，能明其德。", "既建泮宫，淮夷于是归服。", "矫矫虎臣，在泮宫献馘。", "善审如皋陶，在泮宫献囚。", "济济多士，能广大德心。", "桓桓出征，开那东南。", "盛盛皇皇，不大声不张扬。", "不喧讼于争讼，在泮宫献功。", "角弓弯曲。", "束矢众多。", "兵车很宽大。", "步卒车御不厌怠。", "既克淮夷，很善不违逆。", "巩固你的谋略，淮夷终于获平。", "那飞鸮翩翩，停在泮林。", "吃我的桑葚，怀我的好音。", "觉悟的淮夷，来献其珍宝。", "大龟象牙，大赂南方之金。"]};
